const MAX_RENDERED_LOG_ROWS: usize = 128;
/// How many tab stops the PR-layout smoke advances before capturing the
/// keyboard-focus scene, so the ring lands on a control inside the page rather
/// than on the first stop in the window chrome.
#[cfg(feature = "ui-smoke")]
const PR_LAYOUT_SMOKE_TAB_STOPS: usize = 3;
/// Opacity of a disabled control. Low enough to read as unavailable at a glance,
/// high enough that its label stays legible so the user can still see what the
/// control would do once it becomes available.
const DISABLED_OPACITY: f32 = 0.45;

fn bounded_log_render_range(requested: Range<usize>, total: usize) -> Range<usize> {
    let start = requested.start.min(total);
    let end = requested
        .end
        .min(start.saturating_add(MAX_RENDERED_LOG_ROWS))
        .min(total);
    start..end
}

fn normalize_actions_read<T>(
    outcome: cibergit::providers::GeneralReadOutcome<Result<T, ActionsReadError>>,
) -> (
    Result<T, ActionsReadError>,
    Option<cibergit::providers::GeneralReadCache>,
    cibergit::providers::GeneralReadDirective,
) {
    let (outer, cache, directive, failure) = outcome.into_parts();
    let result = outer.unwrap_or_else(|_| {
        Err(ActionsReadError::closed(match failure {
            Some(GeneralReadFailureKind::RateLimited) => ActionsReadErrorCategory::RateLimited,
            Some(GeneralReadFailureKind::Unavailable) => ActionsReadErrorCategory::Unavailable,
            _ => ActionsReadErrorCategory::InvalidResponse,
        }))
    });
    (result, cache, directive)
}
