    #[cfg(feature = "ui-smoke")]
    fn start_pr_layout_smoke(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
        output: PathBuf,
    ) {
        self.install_pr_layout_fixture(window, cx);
        let root = cx.weak_entity();
        window
            .spawn(cx, async move |window| {
                std::fs::create_dir_all(&output).unwrap();
                for (name, section) in [
                    ("conversation", Some(InspectorSection::Overview)),
                    ("commits", Some(InspectorSection::Commits)),
                    ("checks", Some(InspectorSection::Checks)),
                    ("files", None),
                ] {
                    window
                        .update(|window, cx| {
                            root.update(cx, |root, cx| {
                                let Root::Review(this) = root else {
                                    unreachable!()
                                };
                                this.inspector_open = section.is_some();
                                if let Some(section) = section {
                                    this.tabs[0].inspector_section = section;
                                }
                                this.tabs[0].comparison_picker.expanded =
                                    section == Some(InspectorSection::Commits);
                                this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                                this.refresh_auto_layout(window);
                                cx.notify();
                            })
                            .unwrap()
                        })
                        .unwrap();
                    window
                        .background_executor()
                        .timer(Duration::from_millis(400))
                        .await;
                    window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .unwrap()
                                .save(output.join(format!("{name}.png")))
                                .unwrap()
                        })
                        .unwrap();
                }
                // Capture the same sections at the window's minimum size. Wide
                // captures alone cannot show a control crowding or a label
                // clipping, which is exactly where dense rows fail first.
                window
                    .update(|window, _| window.resize(size(px(1040.), px(620.))))
                    .unwrap();
                for (name, section) in [
                    ("conversation", Some(InspectorSection::Overview)),
                    ("files", None),
                ] {
                    window
                        .update(|window, cx| {
                            root.update(cx, |root, cx| {
                                let Root::Review(this) = root else {
                                    unreachable!()
                                };
                                this.inspector_open = section.is_some();
                                if let Some(section) = section {
                                    this.tabs[0].inspector_section = section;
                                }
                                this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                                this.refresh_auto_layout(window);
                                cx.notify();
                            })
                            .unwrap()
                        })
                        .unwrap();
                    window
                        .background_executor()
                        .timer(Duration::from_millis(400))
                        .await;
                    window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .unwrap()
                                .save(output.join(format!("{name}-narrow.png")))
                                .unwrap()
                        })
                        .unwrap();
                }
                // Focus-visible styling resolves only when the focused handle is
                // focused AND the window's last input was a key, so a capture of
                // an idle scene can never show the ring. Dispatch a synthetic
                // in-process Tab to enter keyboard modality, then walk the tab
                // stops. This is application-owned synthetic input; it makes no
                // OS call and requests no activation.
                window
                    .update(|window, cx| {
                        window.resize(size(px(1440.), px(900.)));
                        window.dispatch_event(
                            gpui::PlatformInput::KeyDown(KeyDownEvent {
                                keystroke: gpui::Keystroke::parse("tab").unwrap(),
                                is_held: false,
                                prefer_character_input: false,
                            }),
                            cx,
                        );
                        for _ in 0..PR_LAYOUT_SMOKE_TAB_STOPS {
                            window.focus_next(cx);
                        }
                        assert!(
                            window.last_input_was_keyboard(),
                            "the ring capture must be taken in keyboard modality"
                        );
                        assert!(
                            window.focused(cx).is_some(),
                            "the ring capture must have a focused control"
                        );
                    })
                    .unwrap();
                window
                    .background_executor()
                    .timer(Duration::from_millis(400))
                    .await;
                window
                    .update(|window, _| {
                        window
                            .render_to_image()
                            .unwrap()
                            .save(output.join("keyboard-focus.png"))
                            .unwrap()
                    })
                    .unwrap();
                window.update(|_, cx| cx.quit()).unwrap();
            })
            .detach();
    }

    #[cfg(feature = "ui-smoke")]
    fn start_sidebar_smoke(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
        output: PathBuf,
    ) {
        assert!(
            self.provider_reads_disabled
                && self.accounts.is_empty()
                && self.repositories.is_empty()
        );
        let root = cx.weak_entity();
        window.spawn(cx, async move |window| {
            std::fs::create_dir_all(&output).unwrap();
            // Separate processes can capture each scene without reusing the native
            // offscreen renderer's glyph atlas between exports.
            let scenes: &[bool] = if std::env::var_os("CIBERGIT_SMOKE_SIDEBAR_POPULATED_ONLY").is_some() {
                &[true]
            } else {
                &[false, true]
            };
            for &populated in scenes {
                window.update(|_, cx| {
                    root.update(cx, |root, cx| {
                        let Root::Review(this) = root else { unreachable!() };
                        this.setup_open = false;
                        if populated {
                            let repository = Repository {
                                host: "github.com".into(), owner: "acme".into(), name: "workspace".into(),
                                account: cibergit::domain::Account { host: "github.com".into(), login: "maya".into() },
                                local_path: None,
                            };
                            let pull_requests = [
                                (142, "Keep repository selection on restart", "maya"),
                                (139, "Improve keyboard navigation in the file tree", "alex"),
                                (137, "Fix line wrapping in review comments", "sam"),
                            ].into_iter().map(|(number, title, author)| PullRequest {
                                number, title: title.into(), author: author.into(), state: "OPEN".into(),
                                source_branch: "feature/sidebar".into(), target_branch: "main".into(),
                                ..Default::default()
                            }).collect();
                            this.repositories.push(RepoRuntime {
                                repository, pull_requests: Arc::new(pull_requests), state: LoadState::Ready,
                                generation: 0, refresh: RefreshGate::default(),
                            });
                        }
                        cx.notify();
                    }).unwrap();
                }).unwrap();
                window.background_executor().timer(Duration::from_millis(400)).await;
                window.update(|window, _| {
                    window.render_to_image().unwrap().save(output.join(if populated { "sidebar-populated.png" } else { "sidebar-empty.png" })).unwrap();
                }).unwrap();
            }
            std::fs::write(output.join("report.txt"), "Sidebar layout: synthetic repositories only. Provider bootstrap and polling disabled; no credentials or remote calls. Native sidebar capture; scenarios depend on the requested smoke mode.\n").unwrap();
            window.update(|_, cx| cx.quit()).unwrap();
        }).detach();
    }

    #[cfg(feature = "ui-smoke")]
    fn start_actions_jobs_logs_smoke(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
        output: PathBuf,
    ) {
        let weak = cx.weak_entity();
        window
            .spawn(cx, async move |window| {
                let _ = std::fs::create_dir_all(&output);
                let appearance = std::env::var("CIBERGIT_SMOKE_APPEARANCE")
                    .unwrap_or_else(|_| "system".into());
                let setup = window
                    .update(|window, cx| {
                        window.resize(size(px(1440.), px(900.)));
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else {
                                return Err(
                                    "Actions Jobs/Logs smoke started outside the review workspace"
                                        .to_owned(),
                                );
                            };
                            this.install_actions_jobs_logs_smoke_fixture(window, cx)?;
                            if !this.start_actions_jobs(0, cx) {
                                return Err(
                                    "synthetic Jobs read was refused after fixture admission"
                                        .into(),
                                );
                            }
                            this.focus_current_ci_pane(0, window, cx);
                            Ok(())
                        })
                        .unwrap_or_else(|error| {
                            Err(format!("Actions Jobs/Logs smoke entity unavailable: {error:#}"))
                        })
                    })
                    .unwrap_or_else(|error| {
                        Err(format!("Actions Jobs/Logs smoke window unavailable: {error:#}"))
                    });
                if let Err(error) = setup {
                    let failure = format!("Synthetic Actions Jobs/Logs setup failed: {error}\n");
                    let _ = std::fs::write(
                        output.join(format!(
                            "native-actions-jobs-logs-setup-failure-{appearance}.txt"
                        )),
                        &failure,
                    );
                    panic!("{failure}");
                }

                let jobs_started = std::time::Instant::now();
                let jobs_ready = loop {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(50))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this)
                                    if this.tabs.first().is_some_and(|tab| {
                                        tab.ci_read.pane == CiPane::Jobs
                                            && matches!(tab.ci_read.jobs, MemoryRead::Fresh(_))
                                    })
                                    && this.actions_read_fixture.as_ref().is_some_and(|fixture| {
                                        fixture.jobs_dispatches.load(Ordering::Relaxed) == 1
                                    }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready || jobs_started.elapsed() > Duration::from_secs(5) {
                        break ready;
                    }
                };
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let jobs_name = format!("native-actions-jobs-synthetic-{appearance}.png");
                let jobs_capture = jobs_ready
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image.save(output.join(&jobs_name)).map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);

                let log_started = jobs_capture
                    && window
                        .update(|_, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                this.start_actions_log(0, cx)
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                let log_wait_started = std::time::Instant::now();
                let log_ready = loop {
                    if !log_started {
                        break false;
                    }
                    window
                        .background_executor()
                        .timer(Duration::from_millis(50))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this)
                                    if this.tabs.first().is_some_and(|tab| {
                                        tab.ci_read.pane == CiPane::Log
                                            && matches!(tab.ci_read.log, MemoryRead::Fresh(_))
                                    })
                                    && this.actions_read_fixture.as_ref().is_some_and(|fixture| {
                                        fixture.log_dispatches.load(Ordering::Relaxed) == 1
                                    }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready || log_wait_started.elapsed() > Duration::from_secs(5) {
                        break ready;
                    }
                };
                if log_ready {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(300))
                        .await;
                }
                let tail_requested = log_ready
                    && window
                        .update(|window, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                let Some(tab) = this.tabs.first_mut() else {
                                    return false;
                                };
                                tab.log_horizontal.set_offset(point(px(0.), px(0.)));
                                tab.log_scroll
                                    .scroll_to_item_strict(199_999, ScrollStrategy::Bottom);
                                let inspector_maximum = this.inspector_scroll.max_offset().y;
                                this.inspector_scroll
                                    .set_offset(point(px(0.), -inspector_maximum));
                                this.status = "SYNTHETIC maximum-line Actions log · final row left edge · zero credentials/provider/storage".into();
                                this.focus_current_ci_pane(0, window, cx);
                                cx.notify();
                                true
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(400))
                    .await;
                let left_name = format!("native-actions-log-final-left-synthetic-{appearance}.png");
                let left_capture = tail_requested
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image.save(output.join(&left_name)).map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let (
                    left_materialized,
                    maximum_rendered,
                    horizontal_maximum,
                    inspector_bottom_reached,
                ) = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else {
                                return (false, 0, 0., false);
                            };
                            let Some(tab) = this.tabs.first() else {
                                return (false, 0, 0., false);
                            };
                            let Some(fixture) = &this.actions_read_fixture else {
                                return (false, 0, 0., false);
                            };
                            let inspector_maximum = this.inspector_scroll.max_offset().y.as_f32();
                            let valid_log = tab.ci_read.log.visible().is_some_and(|log| {
                                log.line_count == 200_000
                                    && log
                                        .sanitized_text
                                        .ends_with("SYNTHETIC-HORIZONTAL-END-RIGHT")
                            });
                            (
                                valid_log
                                    && fixture
                                        .final_log_row_materializations
                                        .load(Ordering::Relaxed)
                                        > 0
                                    && tab.log_scroll.is_scrolled_to_end() == Some(true),
                                fixture
                                    .maximum_rendered_log_rows
                                    .load(Ordering::Relaxed),
                                tab.log_horizontal.max_offset().x.as_f32(),
                                inspector_maximum > 0.
                                    && (-this.inspector_scroll.offset().y.as_f32()
                                        - inspector_maximum)
                                        .abs()
                                        < 1.,
                            )
                        })
                        .unwrap_or((false, 0, 0., false))
                    })
                    .unwrap_or((false, 0, 0., false));
                let right_requested = left_capture
                    && left_materialized
                    && inspector_bottom_reached
                    && maximum_rendered > 0
                    && maximum_rendered <= MAX_RENDERED_LOG_ROWS as u64
                    && horizontal_maximum > 1_000.
                    && window
                        .update(|_, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                let Some(tab) = this.tabs.first_mut() else {
                                    return false;
                                };
                                tab.log_horizontal
                                    .set_offset(point(px(-horizontal_maximum), px(0.)));
                                this.status = "SYNTHETIC maximum-line Actions log · final row far-right sentinel · zero credentials/provider/storage".into();
                                cx.notify();
                                true
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let right_name =
                    format!("native-actions-log-final-right-synthetic-{appearance}.png");
                let right_capture = right_requested
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image.save(output.join(&right_name)).map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let right_offset_reached = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            matches!(root, Root::Review(this) if this.tabs.first().is_some_and(
                                |tab| (-tab.log_horizontal.offset().x.as_f32()
                                    - horizontal_maximum)
                                    .abs()
                                    < 1.
                            ))
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                let (jobs_dispatches, log_dispatches, final_materializations) = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else { return (0, 0, 0) };
                            this.actions_read_fixture.as_ref().map_or((0, 0, 0), |fixture| {
                                (
                                    fixture.jobs_dispatches.load(Ordering::Relaxed),
                                    fixture.log_dispatches.load(Ordering::Relaxed),
                                    fixture
                                        .final_log_row_materializations
                                        .load(Ordering::Relaxed),
                                )
                            })
                        })
                        .unwrap_or((0, 0, 0))
                    })
                    .unwrap_or((0, 0, 0));
                let passed = jobs_capture
                    && log_ready
                    && left_capture
                    && left_materialized
                    && inspector_bottom_reached
                    && right_capture
                    && right_offset_reached
                    && jobs_dispatches == 1
                    && log_dispatches == 1
                    && final_materializations > 0
                    && maximum_rendered <= MAX_RENDERED_LOG_ROWS as u64;
                let report = format!(
                    "Native Actions Jobs/Logs synthetic scene ({appearance})\nDisposable data state was empty before scene installation: true\nBootstrap/account/notification/provider reads disabled by smoke-only Startup gate: true\nFixture credential/provider/storage capability: ZERO\nActual Root + GeneralReadController Jobs admission/completion/apply dispatch count: {jobs_dispatches}\nActual Root + GeneralReadController Log admission/completion/apply dispatch count: {log_dispatches}\nJobs capture: {}\nFinal displayed row materializations: {final_materializations}\nMaximum rows in one native render request: {maximum_rendered} (bound {MAX_RENDERED_LOG_ROWS})\nEnclosing inspector bottom reached: {inspector_bottom_reached}\nHorizontal maximum: {horizontal_maximum:.1}px\nFinal row left-edge capture: {}\nFinal row far-right capture: {}\nFar-right offset reached: {right_offset_reached}\nAll identities, jobs, and log text: explicitly synthetic; no live transport or storage compatibility claim\nCredential resolution, /user, API, storage, mutation, OS notification, foreground/focus request, settings, preview, and physical input calls from scene: 0\n",
                    if jobs_capture { &jobs_name } else { "failed" },
                    if left_capture { &left_name } else { "failed" },
                    if right_capture { &right_name } else { "failed" },
                );
                let _ = std::fs::write(
                    output.join(format!("native-actions-jobs-logs-synthetic-{appearance}.txt")),
                    report,
                );
                if !passed {
                    panic!("native Actions Jobs/Logs synthetic scene failed");
                }
                let _ = window.update(|_, cx| cx.quit());
            })
            .detach();
    }

