/// The pinned `gpui_base::Button` is documented as unstyled: it owns focus,
/// keyboard activation and accessibility, and resolves only `selected` and
/// `disabled` styles, so a disabled or keyboard-focused button paints exactly
/// like an idle one unless the application says otherwise. Every control routes
/// both treatments through this trait so they cannot drift apart per surface.
trait ControlPresentation: Sized {
    fn disabled_presentation(self) -> Self;
    fn focus_ring(self, accent: Rgba, fill: Rgba) -> Self;
}

impl ControlPresentation for Button {
    fn disabled_presentation(self) -> Self {
        // Uniform dimming works against any background this app gives a button,
        // including the filled primary action, without inverting its contrast.
        self.styles(|styles| styles.disabled(|style| style.opacity(DISABLED_OPACITY)))
    }

    fn focus_ring(self, accent: Rgba, fill: Rgba) -> Self {
        // `focus_visible` is keyboard-only, so a pointer user never sees a ring
        // after clicking. The ring recolors an existing 1px border and adds the
        // selection fill, which changes no geometry and so cannot reflow a row.
        self.focus_visible(move |style| style.border_color(accent).bg(fill))
    }
}

fn field_label(label: &str, colors: Palette) -> Div {
    div()
        .ui_text(TextRole::Label)
        .text_color(colors.muted)
        .child(label.to_owned())
}

fn input_box(editor: &Entity<InputState>, colors: Palette) -> Div {
    div()
        .mt(px(ui::GAP_FIELD))
        .h(px(ui::CONTROL_HEIGHT))
        .px(px(ui::CELL_INSET))
        .rounded(px(ui::CONTROL_RADIUS))
        .bg(colors.elevated)
        .border_1()
        .border_color(colors.border)
        .font_family(UI_FONT)
        .ui_text(TextRole::Body)
        .child(Input::new(editor))
}

fn editor_field(label: &str, editor: &Entity<InputState>, colors: Palette) -> Div {
    div()
        .flex_1()
        .min_w_0()
        .mb(px(ui::GAP_GROUP))
        .child(field_label(label, colors))
        .child(input_box(editor, colors))
}

fn section_label(label: &str, colors: Palette) -> Div {
    ui::kicker(label)
        .mt(px(ui::GAP_GROUP))
        .mb(px(ui::GAP_GROUP))
        .ui_text(TextRole::Kicker)
        .text_color(colors.faint)
}

/// `announced` carries the control's name for accessibility clients, which
/// matters for the glyph-only reorder controls whose visible label is an arrow.
fn small_action(
    id: impl Into<SharedString>,
    label: &str,
    announced: &str,
    colors: Palette,
) -> Button {
    Button::new(id.into())
        .control()
        .flex_none()
        .justify_start()
        // A transparent border reserves the ring's width up front so gaining
        // focus recolors it instead of resizing the control.
        .border_1()
        .border_color(rgba(0x00000000))
        .ui_text(TextRole::Label)
        .text_color(colors.accent)
        .cursor_pointer()
        .hover(|button| button.bg(colors.selected))
        .accessibility_label(announced.to_owned())
        .disabled_presentation()
        .focus_ring(colors.accent, colors.selected)
        .child(label.to_owned())
}

fn modal_button(
    id: impl Into<SharedString>,
    label: &str,
    primary: bool,
    colors: Palette,
) -> Button {
    Button::new(id.into())
        .control()
        .flex_none()
        .rounded(px(ui::CONTROL_RADIUS))
        .border_1()
        .border_color(if primary {
            colors.accent
        } else {
            colors.border
        })
        .bg(if primary {
            colors.selected
        } else {
            colors.elevated
        })
        .text_color(if primary { colors.accent } else { colors.text })
        .cursor_pointer()
        .hover(|button| button.bg(colors.selected))
        .accessibility_label(label.to_owned())
        .disabled_presentation()
        .focus_ring(colors.accent, colors.selected)
        .child(label.to_owned())
}

fn choice_row(
    label: &str,
    choices: &[(&'static str, bool)],
    colors: Palette,
    cx: &mut Context<Root>,
    select: fn(&mut ReviewWorkspace, usize),
) -> Div {
    let controls = choices
        .iter()
        .enumerate()
        .map(|(index, (label, selected))| {
            side_control(label, *selected, colors)
                .id(SharedString::from(format!(
                    "view-choice-{}-{index}",
                    label.to_ascii_lowercase().replace(' ', "-")
                )))
                .on_click(cx.listener(move |root, _, _, cx| {
                    if let Root::Review(this) = root {
                        select(this, index);
                        cx.notify();
                    }
                }))
        });
    div()
        .mb(px(ui::GAP_GROUP))
        .child(field_label(label, colors))
        .child(
            div()
                .mt_2()
                .flex()
                .flex_wrap()
                .gap(px(ui::GAP_ICON))
                .children(controls),
        )
}

fn view_summary(view: &cibergit::workspace::SavedView) -> String {
    let state = if view.filter.state.is_empty() {
        "open"
    } else {
        view.filter.state.as_str()
    };
    let groups = if view.groups.is_empty() {
        "no grouping".to_owned()
    } else {
        view.groups
            .iter()
            .map(|group| group_label(Some(group)))
            .collect::<Vec<_>>()
            .join(" → ")
    };
    format!("{state} · {groups}")
}

fn file_status_badge(status: &str) -> &'static str {
    match status.to_ascii_lowercase().as_str() {
        "added" | "a" => "A",
        "removed" | "deleted" | "d" => "D",
        "renamed" | "r" => "R",
        "copied" | "c" => "C",
        "changed" | "modified" | "m" => "M",
        _ => "·",
    }
}

// SVG paint requires an explicit foreground; inherited text color is not enough.
fn sidebar_icon(name: &str, color: Rgba) -> Svg {
    let shape = match name {
        "search" => "<circle cx='10.5' cy='10.5' r='6.5'/><path d='m16 16 4 4'/>",
        "bell" => "<path d='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4'/>",
        "panel" => "<rect x='3' y='4' width='18' height='16' rx='3'/><path d='M9 4v16'/>",
        "folder" => {
            "<path d='M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7h18'/>"
        }
        "plus" => "<path d='M12 5v14M5 12h14'/>",
        "more" => {
            "<circle cx='5' cy='12' r='.7'/><circle cx='12' cy='12' r='.7'/><circle cx='19' cy='12' r='.7'/>"
        }
        "edit" => {
            "<path d='M13 4H6a3 3 0 0 0-3 3v11a3 3 0 0 0 3 3h11a3 3 0 0 0 3-3v-7M10 14l1-4L19 2l3 3-8 8-4 1Z'/>"
        }
        "review" => "<rect x='5' y='3' width='14' height='18' rx='3'/><path d='m8 12 3 3 5-6'/>",
        "person" => "<circle cx='12' cy='7' r='4'/><path d='M4 21v-2a8 8 0 0 1 16 0v2'/>",
        "conversation" => {
            "<path d='M21 11a8 8 0 0 1-8 8H8l-5 3V6a3 3 0 0 1 3-3h7a8 8 0 0 1 8 8Z'/>"
        }
        _ => {
            "<circle cx='6' cy='5' r='2'/><circle cx='6' cy='19' r='2'/><circle cx='18' cy='19' r='2'/><path d='M6 7v10M18 17V9a4 4 0 0 0-4-4h-2m3-3-3 3 3 3'/>"
        }
    };
    svg().data(format!("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'>{shape}</svg>").as_bytes())
        .size(px(ui::ICON_SIZE)).flex_none().text_color(color)
}

fn sidebar_icon_button(id: &'static str, label: &str, icon: &str, colors: Palette) -> Button {
    // Reserve the full hit area in layout; painted control remains 28px.
    Button::new(id)
        .debug_selector(move || id.to_owned())
        .group(id)
        .size(px(ui::DESKTOP_HIT))
        .p_0()
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .accessibility_label(label.to_owned())
        // The painted control is 28px inside a 40px target, so the ring is drawn
        // on the target: a focus ring sits outside the control it marks.
        .rounded(px(ui::CONTROL_RADIUS))
        .border_1()
        .border_color(rgba(0x00000000))
        .focus_ring(colors.accent, colors.selected)
        .child(
            div()
                .debug_selector(move || format!("{id}-visual"))
                .size(px(ui::CONTROL_HEIGHT))
                .rounded(px(ui::CONTROL_RADIUS))
                .flex()
                .items_center()
                .justify_center()
                .group_hover(id, |control| control.bg(colors.selected))
                .child(sidebar_icon(icon, colors.muted)),
        )
}

fn sidebar_nav_button(id: String, label: &str, selected: bool, colors: Palette) -> Button {
    let icon = match id.as_str() {
        "open-pr-creation" => "edit",
        "filter-review" => "review",
        "filter-mine" => "person",
        "filter-participating" => "conversation",
        _ => "branch",
    };
    let selector = id.clone();
    Button::new(id)
        .control()
        .debug_selector(move || selector.clone())
        .w_full()
        .h(px(ui::CONTROL_HEIGHT))
        .px(px(ui::CELL_INSET))
        .rounded(px(ui::CONTROL_RADIUS))
        .border_1()
        .border_color(rgba(0x00000000))
        .focus_ring(colors.accent, colors.selected)
        .flex()
        .items_center()
        .gap(px(ui::GAP_ICON))
        .selected(selected)
        .ui_text(TextRole::Body)
        .text_color(if selected { colors.text } else { colors.muted })
        .when(selected, |row| row.bg(colors.selected))
        .hover(|row| row.bg(colors.selected))
        .accessibility_label(format!(
            "{label}{}",
            if selected { ", selected" } else { "" }
        ))
        .child(sidebar_icon(icon, colors.muted))
        .child(
            div()
                .flex_1()
                .min_w_0()
                .overflow_hidden()
                .text_ellipsis()
                .child(label.to_owned()),
        )
}

fn side_control(label: &str, selected: bool, colors: Palette) -> Div {
    div()
        .control()
        .flex_none()
        .max_w(px(CHOICE_MAX_WIDTH))
        .cursor_pointer()
        .ui_text(TextRole::Label)
        .when(selected, |item| {
            item.bg(colors.selected).text_color(colors.text)
        })
        .when(!selected, |item| item.text_color(colors.muted))
        .child(
            div()
                .min_w_0()
                .overflow_hidden()
                .whitespace_nowrap()
                .text_ellipsis()
                .child(label.to_owned()),
        )
}

fn action_link(label: &'static str, colors: Palette) -> Button {
    action_link_with_id(format!("action-{label}"), label, colors)
}

/// A native Button rather than a clickable div: these carry the page's real
/// actions, so they must be reachable with Tab, activate on Enter and Space,
/// and announce themselves as buttons.
fn action_link_with_id(id: String, label: &'static str, colors: Palette) -> Button {
    let selector = id.clone();
    Button::new(SharedString::from(id))
        .debug_selector(move || selector.clone())
        .control()
        .flex_none()
        // Button centers its children; the div this replaced did not. A control
        // that stretches to fill a column keeps its label where it was.
        .justify_start()
        .border_1()
        .border_color(colors.border)
        .cursor_pointer()
        .text_color(colors.accent)
        .hover(|button| button.bg(colors.selected))
        .disabled_presentation()
        .focus_ring(colors.accent, colors.selected)
        // A few callers pass an empty label and supply their own children; an
        // empty announced name would be worse than letting the children speak.
        .when(!label.is_empty(), |button| {
            button.accessibility_label(label)
        })
        .child(label)
}

fn check_identity_button(
    id: String,
    accessibility_label: String,
    selected: bool,
    expanded: bool,
    colors: Palette,
) -> Button {
    Button::new(id)
        .control()
        .h_auto()
        .min_h(px(ui::TWO_LINE_ROW))
        .ui_text(TextRole::Body)
        .mb_2()
        .p(px(ui::CELL_INSET))
        .w_full()
        .flex_col()
        .items_stretch()
        .rounded(px(ui::CONTROL_RADIUS))
        .border_1()
        .border_color(if selected {
            colors.accent
        } else {
            colors.border
        })
        .selected(selected)
        .aria_selected(selected)
        .aria_expanded(expanded)
        .accessibility_label(accessibility_label)
        .when(selected, |row| row.bg(colors.selected))
        .cursor_pointer()
        .hover(|row| row.bg(colors.selected))
}

fn checks_page_button(
    id: &'static str,
    visible_label: &'static str,
    disabled: bool,
    accessibility_label: &'static str,
    colors: Palette,
) -> Button {
    Button::new(id)
        .control()
        .border_1()
        .border_color(colors.border)
        .ui_text(TextRole::Label)
        .text_color(if disabled {
            colors.faint
        } else {
            colors.accent
        })
        .disabled_presentation()
        .focus_ring(colors.accent, colors.selected)
        .disabled(disabled)
        .accessibility_label(accessibility_label)
        .when(!disabled, |button| {
            button
                .cursor_pointer()
                .hover(|button| button.bg(colors.selected))
        })
        .child(visible_label)
}

/// Everything the tip picker renders from.
struct StackTipPicker {
    tips: Vec<cibergit::stacks::StackTipOption>,
    excluded: Vec<cibergit::stacks::StackTipExclusion>,
    current: Option<cibergit::stacks::StackPullRequestId>,
    scroll: gpui::UniformListScrollHandle,
    /// True whenever tips exist but none is compared, so the picker never
    /// disappears while asking for a choice.
    choice_outstanding: bool,
}

/// The Stack tip picker panel. Data in, one choice callback out, so the exact
/// shipped presentation can be rendered without a live review workspace.
fn stack_tip_panel(
    index: usize,
    picker: StackTipPicker,
    colors: Palette,
    on_choose: impl Fn(&cibergit::stacks::StackPullRequestId, &mut App) + Clone + 'static,
) -> impl IntoElement {
    let StackTipPicker {
        tips,
        excluded,
        current,
        scroll,
        choice_outstanding,
    } = picker;
    let tip_count = tips.len();
    div().id("stack-tip-picker").when(
        tip_count > 1 || !excluded.is_empty() || (choice_outstanding && tip_count > 0),
        move |panel| {
            panel
                .flex()
                .flex_col()
                .border_b_1()
                .border_color(colors.border)
                .child(
                    div()
                        .h(px(ui::DESKTOP_HIT))
                        .px(px(ui::CONTROL_INSET))
                        .flex()
                        .items_center()
                        .child(format!("Tips below this PR  {tip_count}")),
                )
                .child(
                    div()
                        .px(px(ui::CONTROL_INSET))
                        .pb_2()
                        .ui_text(TextRole::Caption)
                        .text_color(colors.muted)
                        .child(
                            "Only tips that descend from this pull request are listed. Choose one to compare its path; ⌥⌘T cycles.",
                        ),
                )
                .when(tip_count > 0, |panel| {
                    panel.child(
                        div()
                            .h(px(
                                (ui::TWO_LINE_ROW * tip_count.min(4) as f32).max(ui::TWO_LINE_ROW)
                            ))
                            .min_h(px(ui::TWO_LINE_ROW))
                            .relative()
                            .child(
                                uniform_list(
                                    SharedString::from(format!("stack-tips-{index}")),
                                    tip_count,
                                    move |range: Range<usize>, _, _| {
                                        range
                                            .map(|row| {
                                                let tip = tips[row].clone();
                                                let selected = current.as_ref() == Some(&tip.id);
                                                let choose = on_choose.clone();
                                                let activate = tip.id.clone();
                                                div()
                                                    .w_full()
                                                    .px(px(ui::CELL_INSET))
                                                    .child(
                                                        stack_tip_button(&tip, selected, colors)
                                                            .on_click(move |_, _, cx| {
                                                                choose(&activate, cx);
                                                            }),
                                                    )
                                            })
                                            .collect()
                                    },
                                )
                                .track_scroll(&scroll)
                                .w_full()
                                .h_full(),
                            )
                            .child(
                                div().absolute().inset_0().child(
                                    Scrollbar::vertical(&scroll)
                                        .id(SharedString::from(format!(
                                            "stack-tip-scrollbar-{index}"
                                        )))
                                        .viewport_from_layout(),
                                ),
                            ),
                    )
                })
                .children(excluded.into_iter().map(|excluded| {
                    div()
                        .px(px(ui::CELL_INSET))
                        .py_1()
                        .ui_text(TextRole::Caption)
                        .text_color(colors.amber)
                        .child(format!(
                            "#{} withheld · {}",
                            excluded.id.number, excluded.reason
                        ))
                }))
        },
    )
}

/// One explicitly selectable stack tip. Two lines on the shared 44px two-line
/// row so the branch and the proven path length stay readable.
fn stack_tip_button(
    tip: &cibergit::stacks::StackTipOption,
    selected: bool,
    colors: Palette,
) -> Button {
    let number = tip.id.number;
    Button::new(format!("stack-tip-{number}"))
        .debug_selector(move || format!("stack-tip-{number}"))
        .w_full()
        .min_w_0()
        .h(px(ui::TWO_LINE_ROW))
        .px(px(ui::CELL_INSET))
        .rounded(px(ui::CONTROL_RADIUS))
        .flex()
        .flex_col()
        .justify_center()
        .items_stretch()
        .ui_text(TextRole::Body)
        .cursor_pointer()
        .selected(selected)
        .aria_selected(selected)
        .text_color(if selected { colors.text } else { colors.muted })
        .when(selected, |row| row.bg(colors.selected))
        .hover(|row| row.bg(colors.selected))
        .accessibility_label(format!(
            "Compare tip #{number} on branch {}, {:?}, {} layers on its path{}",
            tip.branch,
            tip.state,
            tip.path_layers,
            if selected { ", selected" } else { "" }
        ))
        .child(
            div()
                .overflow_hidden()
                .whitespace_nowrap()
                .text_ellipsis()
                .child(format!("#{number}  {}", tip.branch)),
        )
        .child(
            div()
                .ui_text(TextRole::Caption)
                .text_color(colors.faint)
                .child(format!(
                    "{:?} · {} layers · {}",
                    tip.state,
                    tip.path_layers,
                    short_sha(&tip.head_sha)
                )),
        )
}

fn short_sha(sha: &str) -> &str {
    &sha[..sha.len().min(8)]
}

fn nonempty_option(value: String) -> Option<String> {
    (!value.trim().is_empty()).then(|| value.trim().to_owned())
}

fn bounded_page(
    total: usize,
    requested_page: usize,
    page_size: usize,
) -> (usize, usize, std::ops::Range<usize>) {
    let pages = total.div_ceil(page_size).max(1);
    let page = requested_page.min(pages - 1);
    let start = page.saturating_mul(page_size).min(total);
    let end = start.saturating_add(page_size).min(total);
    (page, pages, start..end)
}

fn journal_identity(request: &JournalRequest) -> (&str, &str) {
    match request {
        JournalRequest::Auxiliary(request) => (&request.operation_id, &request.attempt_id),
        JournalRequest::Merge { request, .. } => (&request.operation_id, &request.attempt_id),
        JournalRequest::Lifecycle(request) => (&request.operation_id, &request.attempt_id),
        JournalRequest::Discussion(request) => (&request.operation_id, &request.attempt_id),
        JournalRequest::Reaction(request) => (&request.operation_id, &request.attempt_id),
        JournalRequest::Dismissal(request) => (&request.operation_id, &request.attempt_id),
        JournalRequest::ActionsRunControl(request) => (&request.operation_id, &request.attempt_id),
    }
}

fn concise_reconciliation_reason(reason: &str) -> &'static str {
    if reason.contains("does not preserve this local attempt ID") {
        "No remote comment ID was returned, so this attempt cannot be identified."
    } else if reason.contains("incomplete") || reason.contains("truncated") {
        "Provider activity is incomplete, so exact proof is unavailable."
    } else if reason.contains("selected account") || reason.contains("author") {
        "Provider identity did not match the selected account."
    } else if reason.contains("Absence alone")
        || reason.contains("did not contain")
        || reason.contains("returned no pending review")
    {
        "The exact remote object was not observed; absence is not proof."
    } else if reason.contains("could not be applied") {
        "Exact evidence could not be saved to local recovery."
    } else {
        "Provider evidence did not exactly match the frozen request."
    }
}

fn review_reconciliation_description(item: &ReviewReconciliationItem, expanded: bool) -> String {
    let (label, explanation) = match &item.outcome {
        ReviewReconciliationOutcome::Reconciled(evidence) => (
            "Reconciled",
            if expanded {
                evidence.as_str()
            } else {
                "Exact provider evidence matched and recovery was saved."
            },
        ),
        ReviewReconciliationOutcome::Unresolved(reason) => (
            "Still unresolved",
            if expanded {
                reason.as_str()
            } else {
                concise_reconciliation_reason(reason)
            },
        ),
    };
    if expanded {
        format!(
            "{label}: {} / attempt {} · {} · {explanation}",
            item.operation_id, item.attempt_id, item.frozen_request
        )
    } else {
        format!("{label}: {} · {explanation}", item.concise_request)
    }
}

fn journal_operation_summary(operation: &JournalOperation) -> String {
    let action = match &operation.request {
        JournalRequest::Auxiliary(request) => match &request.action {
            ReviewAuxiliaryAction::UpdatePendingSummary { .. } => "Update pending summary",
            ReviewAuxiliaryAction::UpdateSubmittedSummary { .. } => "Edit submitted summary",
            ReviewAuxiliaryAction::DeletePendingComment { .. } => "Delete pending comment",
            ReviewAuxiliaryAction::CancelPendingReview { .. } => "Cancel pending review",
            ReviewAuxiliaryAction::Reply { .. } => "Reply to review thread",
            ReviewAuxiliaryAction::SetThreadResolved { resolved: true, .. } => {
                "Resolve review thread"
            }
            ReviewAuxiliaryAction::SetThreadResolved {
                resolved: false, ..
            } => "Reopen review thread",
        },
        JournalRequest::Merge { request, .. } => match request.action {
            MergeAction::Merge { .. } => "Merge pull request",
            MergeAction::EnableAutoMerge { .. } => "Enable auto-merge",
            MergeAction::DisableAutoMerge => "Disable auto-merge",
            MergeAction::Enqueue => "Add pull request to merge queue",
            MergeAction::Dequeue => "Remove pull request from merge queue",
        },
        JournalRequest::Lifecycle(request) => match &request.action {
            PullRequestLifecycleAction::UpdateTitle { .. } => "Update PR title",
            PullRequestLifecycleAction::UpdateBody { .. } => "Update PR body",
            PullRequestLifecycleAction::UpdateBaseBranch { .. } => "Update PR base branch",
            PullRequestLifecycleAction::Close => "Close pull request",
            PullRequestLifecycleAction::Reopen => "Reopen pull request",
            PullRequestLifecycleAction::ConvertToDraft => "Convert pull request to draft",
            PullRequestLifecycleAction::MarkReadyForReview => "Mark pull request ready",
            PullRequestLifecycleAction::AddReviewer(_) => "Add reviewer",
            PullRequestLifecycleAction::RemoveReviewer(_) => "Remove reviewer",
            PullRequestLifecycleAction::AddLabel(_) => "Add label",
            PullRequestLifecycleAction::RemoveLabel(_) => "Remove label",
            PullRequestLifecycleAction::AddAssignee(_) => "Add assignee",
            PullRequestLifecycleAction::RemoveAssignee(_) => "Remove assignee",
        },
        JournalRequest::Discussion(request) => match request.action {
            PullRequestDiscussionAction::Create { .. } => "Create top-level comment",
            PullRequestDiscussionAction::Edit { .. } => "Edit top-level comment",
            PullRequestDiscussionAction::Delete { .. } => "Delete top-level comment",
        },
        JournalRequest::Reaction(request) => match request.action {
            ReactionAction::Add => "Add reaction",
            ReactionAction::Remove { .. } => "Remove reaction",
        },
        JournalRequest::Dismissal(_) => "Dismiss submitted review",
        JournalRequest::ActionsRunControl(request) => request.preparation.action.label(),
    };
    let reason = match &operation.request {
        JournalRequest::Auxiliary(request)
            if matches!(request.action, ReviewAuxiliaryAction::Reply { .. }) =>
        {
            "Outcome unknown; no exact reply identity is available."
        }
        JournalRequest::Discussion(request)
            if matches!(request.action, PullRequestDiscussionAction::Create { .. }) =>
        {
            "Outcome unknown; the lost create acknowledgement has no exact new comment ID."
        }
        JournalRequest::Discussion(request)
            if matches!(request.action, PullRequestDiscussionAction::Delete { .. }) =>
        {
            "Outcome unknown; absence of the exact comment is not proof this delete applied."
        }
        JournalRequest::Reaction(request) if matches!(request.action, ReactionAction::Add) => {
            "Outcome unknown; a lost add acknowledgement contains no known new reaction ID."
        }
        JournalRequest::Reaction(request)
            if matches!(request.action, ReactionAction::Remove { .. }) =>
        {
            "Outcome unknown; read-only reconciliation may record exact absence but never causation."
        }
        JournalRequest::Dismissal(_) => {
            "Outcome unknown; current DISMISSED state alone cannot prove the frozen reason or causation."
        }
        JournalRequest::ActionsRunControl(_) => {
            "Outcome unknown; GitHub records no per-request Actions control event, so an unmoved run never proves this attempt was not applied."
        }
        _ => "Outcome unknown; use read-only reconciliation before retry.",
    };
    format!("{action} · {reason}")
}

fn journal_operation_description(operation: &JournalOperation) -> String {
    let (operation_id, attempt_id) = journal_identity(&operation.request);
    let frozen = match &operation.request {
        JournalRequest::Auxiliary(request) => match &request.action {
            ReviewAuxiliaryAction::UpdatePendingSummary { review, body } => format!(
                "pending-summary review {} · body {:?}",
                review.remote_id, body
            ),
            ReviewAuxiliaryAction::UpdateSubmittedSummary {
                review,
                selected_author,
                submitted_state,
                submitted_commit_sha,
                expected_body,
                body,
            } => format!(
                "submitted-summary review {} · author {} · state {} · commit {} · old body {:?} · new body {:?}",
                review.remote_id,
                selected_author,
                submitted_state,
                submitted_commit_sha,
                expected_body,
                body
            ),
            ReviewAuxiliaryAction::DeletePendingComment { review, comment } => format!(
                "delete-pending-comment review {} · comment {}",
                review.remote_id, comment.remote_id
            ),
            ReviewAuxiliaryAction::CancelPendingReview { review } => {
                format!("cancel-pending-review {}", review.remote_id)
            }
            ReviewAuxiliaryAction::Reply {
                thread,
                pending_review,
                body,
            } => {
                let pending_review = pending_review
                    .as_ref()
                    .map(|review| format!("pending review {}", review.remote_id))
                    .unwrap_or_else(|| "no pending review ID in the frozen request".into());
                format!(
                    "reply thread {} · {pending_review} · body {:?} · no exact reply ID exists in the frozen request, so GitHub activity cannot prove which reply came from this attempt",
                    thread.remote_id, body
                )
            }
            ReviewAuxiliaryAction::SetThreadResolved { thread, resolved } => format!(
                "set-thread-resolved thread {} · resolved={resolved}",
                thread.remote_id
            ),
        },
        JournalRequest::Merge {
            preparation,
            request,
        } => format!(
            "merge {:?} · PR {} · reviewed head {} · current head {}",
            request.action,
            preparation.pull_request.remote_id,
            preparation.reviewed_head_sha,
            preparation.current_head_sha
        ),
        JournalRequest::Lifecycle(request) => format!(
            "lifecycle {:?} · PR {} · observed updated {} · state {} · head {}",
            request.action,
            request.target.pull_request.remote_id,
            request.target.observed_updated_at,
            request.target.observed_state,
            request.target.observed_head_sha
        ),
        JournalRequest::Discussion(request) => format!(
            "top-level discussion {:?} · PR {} · observed updated {} · state {} · head {}",
            request.action,
            request.target.pull_request.remote_id,
            request.target.observed_updated_at,
            request.target.observed_state,
            request.target.observed_head_sha
        ),
        JournalRequest::Reaction(request) => format!(
            "reaction {:?} · kind {:?} · subject {} · parent {:?} · PR {} · viewer {} ({}) · content {} · subject content {:?}",
            request.action,
            request.target.kind,
            request.target.subject.remote_id,
            request
                .target
                .parent_review
                .as_ref()
                .map(|parent| parent.remote_id.as_str()),
            request.target.pull_request.remote_id,
            request.viewer.login,
            request.viewer.node_id,
            request.content.graphql_name(),
            request.target.content,
        ),
        JournalRequest::Dismissal(request) => format!(
            "dismiss submitted review {} · parent PR {} · repository {} · viewer {} ({}) · state {} · submitted {} · author {:?} · commit {:?} · body {:?} · reason {:?} · authority {:?}",
            request.target.review.remote_id,
            request.target.pull_request.remote_id,
            request.target.repository.full_name(),
            request.viewer.login,
            request.viewer.node_id,
            request.target.review_state,
            request.target.submitted_at,
            request.target.review_author,
            request.target.review_commit_sha,
            request.target.review_body,
            request.reason,
            request.authority,
        ),
        JournalRequest::ActionsRunControl(request) => {
            let preparation = &request.preparation;
            let target = &preparation.observation.target;
            format!(
                "{} · repository {} · PR #{} · workflow {} ({}) · run {} ({}) · run number {} · attempt {} · event {} · head {} · check {} ({}) · suite {} · observed status {}{} · viewer {} ({}) · authority {:?} · exact request {} /{} {}",
                preparation.action.label(),
                target.repository_name_with_owner,
                target.pull_request_number,
                target.workflow_name,
                target.workflow_node_id,
                target.run_database_id,
                target.run_node_id,
                target.run_number,
                target.run_attempt,
                target.run_event,
                target.run_head_sha,
                target.check_node_id,
                target.check_database_id,
                target.check_suite_node_id,
                preparation.observation.run_status,
                preparation
                    .observation
                    .run_conclusion
                    .as_deref()
                    .map(|value| format!(" · {value}"))
                    .unwrap_or_default(),
                preparation.observation.viewer.login,
                preparation.observation.viewer.node_id,
                preparation.observation.authority,
                preparation.method,
                preparation.path,
                preparation.body,
            )
        }
    };
    let status = match &operation.status {
        JournalStatus::InFlight => {
            "process stopped before a durable outcome was recorded".to_owned()
        }
        JournalStatus::Uncertain { reason } => reason.clone(),
        JournalStatus::Acknowledged { summary, .. } => summary.clone(),
        JournalStatus::NotApplied { evidence } => evidence.clone(),
    };
    format!("{operation_id} / attempt {attempt_id} · {frozen} · {status}")
}

fn observe_auxiliary(
    action: &ReviewAuxiliaryAction,
    details: &PullRequestDetails,
    pending: Option<&cibergit::domain::PendingReviewSnapshot>,
) -> Option<(bool, bool, String)> {
    match action {
        ReviewAuxiliaryAction::UpdatePendingSummary { review, body } => {
            let observed = pending
                .filter(|snapshot| snapshot.review.coordinates.remote_id == review.remote_id)?;
            (observed.review.body == *body).then(|| {
                (
                    true,
                    true,
                    "Authoritative pending-review body matched the exact request payload.".into(),
                )
            })
        }
        ReviewAuxiliaryAction::UpdateSubmittedSummary {
            review,
            selected_author,
            submitted_state,
            submitted_commit_sha,
            body,
            ..
        } => {
            let observed = details.reviews.iter().find(|candidate| {
                candidate.coordinates == *review
                    && candidate.body == *body
                    && candidate.state == *submitted_state
                    && candidate.submitted_at.is_some()
                    && candidate.commit_sha.as_deref() == Some(submitted_commit_sha.as_str())
                    && candidate
                        .author
                        .as_deref()
                        .is_some_and(|author| author.eq_ignore_ascii_case(selected_author))
            })?;
            let _ = observed;
            Some((
                true,
                true,
                "Fresh exact review identity, parent coordinates, body, submitted state, author, and commit match the frozen requested final state. This establishes current convergence, not local causation."
                    .into(),
            ))
        }
        ReviewAuxiliaryAction::DeletePendingComment { review, comment } => {
            let _observed = pending.filter(|snapshot| {
                snapshot.review.coordinates.remote_id == review.remote_id
                    && snapshot.comments_complete
            })?;
            let _ = comment;
            // Absence can be caused by a later external deletion or submission;
            // presence does not prove which attempt failed. GitHub exposes no
            // attempt correlation for this mutation.
            None
        }
        ReviewAuxiliaryAction::CancelPendingReview { review } => {
            let _ = review;
            // A missing pending review may have been submitted or cancelled by
            // another actor, so absence alone cannot identify this attempt.
            None
        }
        ReviewAuxiliaryAction::SetThreadResolved { thread, resolved } => {
            let observed = details
                .review_threads
                .iter()
                .find(|candidate| candidate.coordinates.remote_id == thread.remote_id)?;
            (observed.resolved == *resolved).then(|| {
                (
                    true,
                    true,
                    "Authoritative thread read matched the exact ID and resolution payload.".into(),
                )
            })
        }
        ReviewAuxiliaryAction::Reply { .. } => None,
    }
}

fn observe_merge(
    action: &MergeAction,
    prepared: &MergePreparation,
    fresh: &MergePreparation,
) -> Option<(bool, bool, String)> {
    if fresh.pull_request.remote_id != prepared.pull_request.remote_id {
        return None;
    }
    let merged = fresh.state == "MERGED";
    let applied = match action {
        MergeAction::Merge { .. } => merged,
        MergeAction::EnableAutoMerge { .. } => fresh.auto_merge_enabled || merged,
        MergeAction::DisableAutoMerge => !fresh.auto_merge_enabled,
        MergeAction::Enqueue => fresh.in_merge_queue || merged,
        MergeAction::Dequeue => !fresh.in_merge_queue,
    };
    Some((
        applied,
        merged,
        format!(
            "Fresh provider state for exact PR/head: state={}, auto_merge={}, queued={}",
            fresh.state, fresh.auto_merge_enabled, fresh.in_merge_queue
        ),
    ))
}

