    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn density_controls_keep_visual_metrics_and_real_hit_targets(cx: &mut gpui::TestAppContext) {
        use cibergit::ui::{self, Density, TextRole};
        use gpui::{prelude::*, *};
        struct Harness {
            input: Entity<gpui_base::input::InputState>,
            clicks: Rc<Cell<usize>>,
        }
        impl Render for Harness {
            fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
                let colors = super::palette(false);
                let clicks = self.clicks.clone();
                div()
                    .size_full()
                    .p(px(ui::PANEL_GUTTER))
                    .ui_text(TextRole::Body)
                    .child(
                        super::field_label("Repository", colors)
                            .debug_selector(|| "density-label".into()),
                    )
                    .child(
                        super::input_box(&self.input, colors)
                            .debug_selector(|| "density-input".into()),
                    )
                    .child(
                        super::modal_button("density-button", "Add repository", true, colors)
                            .debug_selector(|| "density-button".into()),
                    )
                    .child(
                        div()
                            .badge()
                            .debug_selector(|| "density-badge".into())
                            .child("Open"),
                    )
                    .child(
                        super::command_row("Open Checks", "⇧⌘C", colors)
                            .debug_selector(|| "density-menu".into()),
                    )
                    .child(super::sidebar_nav_button(
                        "density-nav".into(),
                        "Pull requests",
                        true,
                        colors,
                    ))
                    .child(
                        super::sidebar_icon_button("density-icon", "Search", "search", colors)
                            .on_click(move |_, _, _| clicks.set(clicks.get() + 1)),
                    )
            }
        }
        cx.update(gpui_base::init);
        let clicks = Rc::new(Cell::new(0));
        let (_, cx) = cx.add_window_view(|window, cx| Harness {
            input: cx.new(|cx| gpui_base::input::InputState::new(window, cx)),
            clicks: clicks.clone(),
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        for (id, height) in [
            ("density-label", 16.),
            ("density-input", 28.),
            ("density-button", 28.),
            ("density-badge", 20.),
            ("density-menu", 28.),
            ("density-nav", 28.),
            ("density-icon", 40.),
            ("density-icon-visual", 28.),
        ] {
            assert_eq!(cx.debug_bounds(id).unwrap().size.height, px(height), "{id}");
        }
        let label = cx.debug_bounds("density-label").unwrap();
        let input = cx.debug_bounds("density-input").unwrap();
        assert_eq!(input.top() - label.bottom(), px(6.));
        assert_eq!(input.left(), px(20.));
        let target = cx.debug_bounds("density-icon").unwrap();
        let visual = cx.debug_bounds("density-icon-visual").unwrap();
        let edge = target.origin + point(px(2.), px(2.));
        assert!(!visual.contains(&edge));
        cx.simulate_click(edge, Modifiers::default());
        assert_eq!(
            clicks.get(),
            1,
            "padding outside the painted icon must be clickable"
        );
    }

    /// Discriminating keyboard check on the REAL review window, not a harness.
    /// A bare harness can pass while production fails, because production has
    /// the full dispatch tree, registered key bindings and a deep element
    /// hierarchy. This drives an actual inspector Button with actual keys.
    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn real_inspector_buttons_take_tab_focus_and_activate_on_enter_and_space(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{KeyDownEvent, KeyUpEvent, Keystroke};

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.install_pr_layout_fixture(window, cx);
            });
            window.draw(cx).clear(cx);
        });

        // Open Checks, which holds a real production disclosure Button.
        let checks = cx.debug_bounds("pr-tab-checks").unwrap();
        cx.simulate_click(checks.center(), Modifiers::default());
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert!(
            cx.debug_bounds("checks-source-details").is_some(),
            "the fixture must render the inspector disclosure control"
        );

        // Tab must actually move focus in the real window. Production registers
        // no tab_group anywhere, so this is the property that would break if a
        // group were required to build the tab-stop tree.
        let mut focus_moved = false;
        for _ in 0..40 {
            let before = cx.update(|window, cx| window.focused(cx));
            cx.update(|window, cx| window.focus_next(cx));
            let after = cx.update(|window, cx| window.focused(cx));
            if after.is_some() && before != after {
                focus_moved = true;
                break;
            }
        }
        assert!(
            focus_moved,
            "Tab must move focus in the real review window; if this fails the \
             tab-stop tree is not being built at all"
        );

        // The Checks-specific activation regression below verifies the pane
        // shortcut no longer intercepts Enter on a focused child control.
        // This test separately covers a file-header action in the real window.

        // Now the discriminating half. Go to Files, which holds a converted
        // action control, and use its focus ring to CONFIRM which control the
        // keyboard actually reached before pressing anything. Cycling blindly
        // and hoping proves nothing about where the key landed.
        let files_tab = cx.debug_bounds("pr-tab-files").unwrap();
        cx.simulate_click(files_tab.center(), Modifiers::default());
        cx.update(|window, cx| window.draw(cx).clear(cx));
        let control = cx
            .debug_bounds("comment-on-file")
            .expect("the fixture must render the file comment action");

        let accent: gpui::Hsla = super::palette(false).accent.into();
        let focused_here = |cx: &mut gpui::VisualTestContext| {
            cx.update(|window, _| {
                let scaled = control.scale(window.scale_factor());
                window.painted_quads().into_iter().any(|quad| {
                    quad.border_color == accent
                        && quad.border_widths.top > gpui::ScaledPixels(0.)
                        && quad.bounds == scaled
                })
            })
        };

        // Enter keyboard modality so the ring resolves at all.
        let tab = Keystroke::parse("tab").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: tab.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent { keystroke: tab });

        // Enter keyboard modality with a real keystroke first. The passing
        // main-window test did this; this one did not, and modality is the only
        // remaining difference between them.
        let tab_key = Keystroke::parse("tab").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: tab_key.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent { keystroke: tab_key });
        let mut reached = false;
        for _ in 0..200 {
            cx.update(|window, cx| window.focus_next(cx));
            // GPUI registers a focused element's Enter/Space handlers during
            // paint, guarded by `is_focused`, so focus must be painted before
            // the key is sent or the press is silently lost.
            cx.update(|window, cx| window.draw(cx).clear(cx));
            if focused_here(cx) {
                reached = true;
                break;
            }
        }
        assert!(
            reached,
            "Tab must reach the file comment action in the real window, and it \
             must paint its ring so focus is observable rather than assumed"
        );

        // Activating opens the file composer and moves focus into it, so each
        // key re-acquires focus first. The observable is the workspace status
        // the real handler sets.
        let status_of = |cx: &mut gpui::VisualTestContext| {
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.status.clone()
            })
        };
        for key in ["enter", "space"] {
            let mut focused = focused_here(cx);
            for _ in 0..200 {
                if focused {
                    break;
                }
                cx.update(|window, cx| window.focus_next(cx));
                cx.update(|window, cx| window.draw(cx).clear(cx));
                focused = focused_here(cx);
            }
            assert!(focused, "Tab must reach the control again before {key}");

            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.status = format!("before-{key}");
                cx.notify();
            });
            cx.update(|window, cx| window.draw(cx).clear(cx));

            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
            cx.update(|window, cx| window.draw(cx).clear(cx));

            assert_ne!(
                status_of(cx),
                format!("before-{key}"),
                "a confirmed-focused production control must activate on {key}; \
                 if this fails, {key} never reaches the control in the real \
                 dispatch tree even though Tab reached it"
            );
        }
    }

    /// The Checks inspector keyboard defect, asserted rather than described.
    ///
    /// This asks the two questions separately and with no ring involved, using
    /// the control's own caller-owned FocusHandle, so neither answer can be
    /// confounded by a clipped quad or by mouse modality:
    ///   1. does Tab traversal ever land focus on the control, and
    ///   2. once it is genuinely focused, does Enter activate it.
    /// Both are driven on the real review window with a redraw between focusing
    /// and pressing, because GPUI only registers a focused element's Enter and
    /// Space listeners while painting it focused.
    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn checks_inspector_control_is_tab_reachable_and_activates(cx: &mut gpui::TestAppContext) {
        use gpui::{KeyDownEvent, KeyUpEvent, Keystroke};

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.install_pr_layout_fixture(window, cx);
            });
            window.draw(cx).clear(cx);
        });
        let checks = cx.debug_bounds("pr-tab-checks").unwrap();
        cx.simulate_click(checks.center(), Modifiers::default());
        cx.update(|window, cx| window.draw(cx).clear(cx));
        // debug_bounds is recorded before the visibility early-return and
        // regardless of clipping, so a bounds value alone proves nothing about
        // whether the control is actually on screen. Establish that first, or an
        // offscreen fixture layout would masquerade as a traversal defect.
        let control = cx
            .debug_bounds("checks-source-details")
            .expect("the disclosure must be painted for this regression to mean anything");
        let viewport = cx.update(|window, _| window.viewport_size());
        let visible_area = gpui::Bounds {
            origin: gpui::point(px(0.), px(0.)),
            size: viewport,
        };
        assert!(
            control.intersects(&visible_area),
            "the disclosure must lie inside the window viewport; if it does not, \
             this is an offscreen fixture layout rather than a keyboard defect"
        );
        assert!(
            control.size.width > px(0.) && control.size.height > px(0.),
            "the disclosure must have real painted area, not a collapsed box"
        );
        // The window viewport is not the binding clip: the inspector scrolls
        // inside the PR content region, so check the real ancestor too.
        if let Some(page) = cx.debug_bounds("pr-section-page") {
            assert!(
                control.intersects(&page),
                "the disclosure must lie inside the PR content region it scrolls \
                 within; if it does not, it is scrolled out of view and this is a \
                 fixture layout question, not a keyboard defect"
            );
        }

        let is_focused = |cx: &mut gpui::VisualTestContext| {
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.checks_details_focus.clone()
            })
        };
        let focused_now = |cx: &mut gpui::VisualTestContext| {
            let handle = is_focused(cx);
            cx.update(|window, _| handle.is_focused(window))
        };

        let mut reached = false;
        for _ in 0..200 {
            cx.update(|window, cx| window.focus_next(cx));
            cx.update(|window, cx| window.draw(cx).clear(cx));
            if focused_now(cx) {
                reached = true;
                break;
            }
        }
        assert!(
            reached,
            "Tab traversal must land on the Checks disclosure; it is painted \
             every frame, so if this fails the control is absent from the tab \
             ring rather than merely hard to see"
        );

        let expanded_before = root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            this.tabs[0].checks_source_expanded
        });
        let enter = Keystroke::parse("enter").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: enter.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent { keystroke: enter });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert_ne!(
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.tabs[0].checks_source_expanded
            }),
            expanded_before,
            "a genuinely focused Checks disclosure must activate on Enter"
        );

        let before_space = root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            this.tabs[0].checks_source_expanded
        });
        let space = Keystroke::parse("space").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: space.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent { keystroke: space });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert_ne!(
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.tabs[0].checks_source_expanded
            }),
            before_space,
            "the same control must also activate on Space"
        );

        // The pane shortcut must survive the fix: with focus back on the pane
        // itself rather than a control, Enter still toggles the selected check
        // identity. Guarding the shortcut must not delete it.
        let identity_before = root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            this.tabs[0].checks_selection.expanded_id.clone()
        });
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.checks_focus.focus(window, cx);
            });
            window.draw(cx).clear(cx);
        });
        let enter_again = Keystroke::parse("enter").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: enter_again.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent {
            keystroke: enter_again,
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert_ne!(
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.tabs[0].checks_selection.expanded_id.clone()
            }),
            identity_before,
            "the pane-level Enter shortcut must still work when the pane itself \
             holds focus"
        );
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn pr_tabs_and_splitters_follow_real_pointer_input(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.install_pr_layout_fixture(window, cx);
            });
            window.draw(cx).clear(cx);
        });
        for id in ["pr-tab-commits", "pr-tab-checks", "pr-tab-conversation"] {
            let bounds = cx.debug_bounds(id).unwrap();
            cx.simulate_click(bounds.center(), Modifiers::default());
            cx.update(|window, cx| window.draw(cx).clear(cx));
            let page = cx.debug_bounds("pr-section-page").unwrap();
            assert!(
                page.size.width > px(800.),
                "PR content is squeezed into a sidebar"
            );
            if id == "pr-tab-checks" {
                let disclosure = cx.debug_bounds("checks-source-details").unwrap();
                cx.simulate_click(disclosure.center(), Modifiers::default());
                root.read_with(cx, |root, _| {
                    let Root::Review(this) = root else {
                        unreachable!()
                    };
                    assert!(this.tabs[0].checks_source_expanded);
                });
                cx.update(|window, cx| window.draw(cx).clear(cx));
                let disclosure = cx.debug_bounds("checks-source-details").unwrap();
                cx.simulate_click(disclosure.center(), Modifiers::default());
                cx.update(|window, cx| window.draw(cx).clear(cx));
            }
        }
        let files = cx.debug_bounds("pr-tab-files").unwrap();
        cx.simulate_click(files.center(), Modifiers::default());
        cx.update(|window, cx| window.draw(cx).clear(cx));
        for _ in 0..2 {
            let was_split = root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.tabs[0].diff_split
            });
            let toggle = cx.debug_bounds("toggle-diff-layout").unwrap();
            cx.simulate_click(toggle.center(), Modifiers::default());
            cx.update(|window, cx| window.draw(cx).clear(cx));
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert_eq!(this.tabs[0].diff_split, !was_split);
                assert_eq!(
                    this.tabs[0].session.as_ref().unwrap().diff_mode(),
                    if was_split {
                        DiffMode::Unified
                    } else {
                        DiffMode::SideBySide
                    }
                );
            });
        }
        for (selector, panel) in [
            ("splitter-Sidebar", super::PanelKind::Sidebar),
            ("splitter-FileTree", super::PanelKind::FileTree),
        ] {
            let bounds = cx.debug_bounds(selector).unwrap();
            let start = bounds.center();
            let before = root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.panel_layout.width(panel, false)
            });
            cx.simulate_mouse_down(start, gpui::MouseButton::Left, Modifiers::default());
            cx.simulate_mouse_move(
                start + point(px(10.), px(0.)),
                gpui::MouseButton::Left,
                Modifiers::default(),
            );
            cx.update(|window, cx| window.draw(cx).clear(cx));
            cx.simulate_mouse_move(
                start + point(px(70.), px(0.)),
                gpui::MouseButton::Left,
                Modifiers::default(),
            );
            cx.update(|window, cx| window.draw(cx).clear(cx));
            let enlarged = root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.panel_layout.width(panel, false)
            });
            assert!(
                (enlarged - before - 60.).abs() < 2.,
                "{selector}: {before} -> {enlarged}"
            );
            // Reverse while held, far beyond the original six-pixel hit target.
            cx.simulate_mouse_move(
                start + point(px(30.), px(0.)),
                gpui::MouseButton::Left,
                Modifiers::default(),
            );
            cx.update(|window, cx| window.draw(cx).clear(cx));
            let reversed = root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.panel_layout.width(panel, false)
            });
            assert!((reversed - before - 20.).abs() < 2.);
            cx.simulate_mouse_up(
                start + point(px(30.), px(0.)),
                gpui::MouseButton::Left,
                Modifiers::default(),
            );
            cx.simulate_mouse_move(start + point(px(90.), px(0.)), None, Modifiers::default());
            cx.update(|window, cx| window.draw(cx).clear(cx));
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert_eq!(this.panel_layout.width(panel, false), reversed);
                let session = this.tabs[0].session.as_ref().unwrap();
                assert_eq!(session.revision().head_sha, "2".repeat(40));
                assert_eq!(session.selected_file().unwrap().path, "src/navigation.rs");
                assert!(!this.tabs[0].write_in_flight);
            });
        }
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn repository_setup_picker_and_manual_submission_report_errors(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let selected = data.path().join("folder with spaces");
        fs::create_dir(&selected).unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().join("app-data")),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.dispatch_action(super::OpenRepositorySetup);
        assert!(cx.did_prompt_for_paths());
        cx.simulate_path_prompt_response(|options| {
            assert!(options.directories);
            assert!(!options.files && !options.multiple);
            Some(vec![selected.clone()])
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert!(this.setup_open);
                assert!(!this.repository_picker_open);
                assert_eq!(
                    this.repository_input.read(cx).value().as_str(),
                    selected.to_str().unwrap()
                );
                // Cancelling a second picker must retain the selected/manual path.
                this.open_repository_picker(window, cx);
            });
        });
        cx.simulate_path_prompt_response(|_| None);
        cx.run_until_parked();
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert_eq!(
                    this.repository_input.read(cx).value().as_str(),
                    selected.to_str().unwrap()
                );
                this.repository_input
                    .update(cx, |input, cx| input.focus(window, cx));
            });
        });
        // Exercise the input's actual Return event, with no discovered account.
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else { unreachable!() };
                assert!(matches!(&this.repository_setup_state, LoadState::Error(message) if message.contains("gh auth login")));
                assert!(this.setup_open && this.repositories.is_empty());
                this.accounts.push(Account { host: "github.com".into(), login: "fixture".into() });
                // The selected directory is not a Git repository: fail locally before credentials/network.
                this.submit_repository_setup(cx);
                assert!(matches!(this.repository_setup_state, LoadState::Loading(_)));
            });
        });
        cx.run_until_parked();
        cx.update(|_, cx| {
            root.update(cx, |root, _| {
                let Root::Review(this) = root else { unreachable!() };
                assert!(matches!(&this.repository_setup_state, LoadState::Error(message) if message.contains("Cannot add repository")));
                assert!(this.setup_open && this.repositories.is_empty());
            });
        });
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        assert!(cx.debug_bounds("repository-setup-notice").is_some());
    }

