    #[test]
    fn log_render_window_is_bounded_and_reaches_final_sentinel() {
        let text = (0..200_000)
            .map(|index| {
                if index == 199_999 {
                    "FINAL-SENTINEL".to_owned()
                } else {
                    format!("line-{index}")
                }
            })
            .collect::<Vec<_>>()
            .join("\n");
        let broad = bounded_log_render_range(0..200_000, 200_000);
        assert_eq!(broad.len(), super::MAX_RENDERED_LOG_ROWS);
        let tail = bounded_log_render_range(199_999..200_000, 200_000);
        let rendered = text
            .split_terminator('\n')
            .skip(tail.start)
            .take(tail.len())
            .collect::<Vec<_>>();
        assert_eq!(rendered, ["FINAL-SENTINEL"]);
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn stack_tip_picker_row_exposes_selection_and_pointer_keyboard_activation(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{
            Context, KeyDownEvent, KeyUpEvent, Keystroke, Modifiers, Render, accesskit, canvas,
            div, point, prelude::*, px,
        };
        use std::{
            cell::{Cell, RefCell},
            rc::Rc,
        };

        fn tip(number: u64, selected_branch: &str) -> cibergit::stacks::StackTipOption {
            cibergit::stacks::StackTipOption {
                id: cibergit::stacks::StackPullRequestId {
                    repository: cibergit::stacks::StackRepository {
                        host: "github.com".into(),
                        owner: "owner".into(),
                        name: "repo".into(),
                    },
                    number,
                },
                branch: selected_branch.into(),
                head_sha: "c".repeat(40),
                state: cibergit::stacks::StackLayerState::Open,
                path_layers: 3,
            }
        }

        struct Harness {
            activations: Rc<Cell<usize>>,
        }

        impl Render for Harness {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let activations = self.activations.clone();
                div().size(px(240.)).child(
                    stack_tip_button(&tip(7, "feature-upper"), false, palette(false))
                        .size_full()
                        .on_click(move |_, _, _| activations.set(activations.get() + 1)),
                )
            }
        }

        type Captured = Rc<RefCell<Option<(Option<gpui::Role>, accesskit::Node, accesskit::Node)>>>;

        struct Probe {
            captured: Captured,
        }

        impl Render for Probe {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let captured = self.captured.clone();
                canvas(
                    move |_, window, cx| {
                        let colors = palette(false);
                        let describe =
                            |selected: bool, window: &mut gpui::Window, cx: &mut gpui::App| {
                                let element =
                                    stack_tip_button(&tip(7, "feature-upper"), selected, colors)
                                        .on_click(|_, _, _| {})
                                        .render(window, cx)
                                        .into_element();
                                let role = element.a11y_role();
                                let mut node =
                                    accesskit::Node::new(role.unwrap_or(gpui::Role::Unknown));
                                element.write_a11y_info(&mut node);
                                (role, node)
                            };
                        let (role, unselected) = describe(false, window, cx);
                        let (_, selected) = describe(true, window, cx);
                        *captured.borrow_mut() = Some((role, unselected, selected));
                    },
                    |_, _, _, _| {},
                )
            }
        }

        cx.update(gpui_base::init);
        let captured = Rc::new(RefCell::new(None));
        let (_, probe_window) = cx.add_window_view({
            let captured = captured.clone();
            move |_, _| Probe { captured }
        });
        probe_window.update(|window, cx| window.draw(cx).clear(cx));
        let (role, unselected, selected) = captured.borrow_mut().take().unwrap();

        // A tip is a real button that states its identity, its proven path
        // length, and whether it is the tip currently being compared.
        assert_eq!(role, Some(gpui::Role::Button));
        assert_eq!(
            unselected.label(),
            Some("Compare tip #7 on branch feature-upper, Open, 3 layers on its path")
        );
        assert_eq!(unselected.is_selected(), Some(false));
        assert_eq!(
            selected.label(),
            Some("Compare tip #7 on branch feature-upper, Open, 3 layers on its path, selected")
        );
        assert_eq!(selected.is_selected(), Some(true));
        assert!(unselected.supports_action(accesskit::Action::Click));

        let activations = Rc::new(Cell::new(0));
        let (_, cx) = cx.add_window_view({
            let activations = activations.clone();
            move |_, _| Harness { activations }
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(point(px(12.), px(12.)), Modifiers::default());
        for key in ["enter", "space"] {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
        }
        assert_eq!(
            activations.get(),
            3,
            "pointer, Enter and Space each choose the tip"
        );
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn checks_buttons_expose_accessibility_and_pointer_keyboard_semantics(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{
            Context, KeyDownEvent, KeyUpEvent, Keystroke, Modifiers, Render, accesskit, canvas,
            div, point, prelude::*, px,
        };
        use std::{
            cell::{Cell, RefCell},
            rc::Rc,
        };

        struct Harness {
            disabled: bool,
            activations: Rc<Cell<usize>>,
        }

        impl Render for Harness {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let activations = self.activations.clone();
                let colors = palette(false);
                div().size(px(120.)).child(if self.disabled {
                    checks_page_button(
                        "checks-disabled-witness",
                        "Previous 40",
                        true,
                        "Previous 40 checks, unavailable on the first page",
                        colors,
                    )
                    .size_full()
                    .on_click(move |_, _, _| activations.set(activations.get() + 1))
                } else {
                    check_identity_button(
                        "checks-row-witness".into(),
                        "CI; Check run; Required; head; linked; selected; expanded".into(),
                        true,
                        true,
                        colors,
                    )
                    .size_full()
                    .on_click(move |_, _, _| activations.set(activations.get() + 1))
                })
            }
        }

        type CapturedAccessibility = Rc<
            RefCell<
                Option<(
                    Option<gpui::Role>,
                    accesskit::Node,
                    Option<gpui::Role>,
                    accesskit::Node,
                )>,
            >,
        >;

        struct AccessibilityProbe {
            captured: CapturedAccessibility,
        }

        impl Render for AccessibilityProbe {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let captured = self.captured.clone();
                canvas(
                    move |_, window, cx| {
                        let colors = palette(false);
                        let row_element = check_identity_button(
                            "checks-row-a11y".into(),
                            "CI; selected; expanded".into(),
                            true,
                            true,
                            colors,
                        )
                        .on_click(|_, _, _| {})
                        .render(window, cx)
                        .into_element();
                        let row_role = row_element.a11y_role();
                        let mut row_node =
                            accesskit::Node::new(row_role.unwrap_or(gpui::Role::Unknown));
                        row_element.write_a11y_info(&mut row_node);

                        let disabled_element = checks_page_button(
                            "checks-page-a11y",
                            "Previous 40",
                            true,
                            "Previous 40 checks, unavailable on the first page",
                            colors,
                        )
                        .on_click(|_, _, _| {})
                        .render(window, cx)
                        .into_element();
                        let disabled_role = disabled_element.a11y_role();
                        let mut disabled_node =
                            accesskit::Node::new(disabled_role.unwrap_or(gpui::Role::Unknown));
                        disabled_element.write_a11y_info(&mut disabled_node);
                        *captured.borrow_mut() =
                            Some((row_role, row_node, disabled_role, disabled_node));
                    },
                    |_, _, _, _| {},
                )
            }
        }

        cx.update(gpui_base::init);
        let captured = Rc::new(RefCell::new(None));
        let (_, probe_window) = cx.add_window_view({
            let captured = captured.clone();
            move |_, _| AccessibilityProbe { captured }
        });
        probe_window.update(|window, cx| window.draw(cx).clear(cx));
        let (row_role, row_node, disabled_role, disabled_node) =
            captured.borrow_mut().take().unwrap();
        assert_eq!(row_role, Some(gpui::Role::Button));
        assert_eq!(row_node.label(), Some("CI; selected; expanded"));
        assert_eq!(row_node.is_selected(), Some(true));
        assert_eq!(row_node.is_expanded(), Some(true));
        assert!(row_node.supports_action(accesskit::Action::Click));
        assert_eq!(disabled_role, Some(gpui::Role::Button));
        assert_eq!(
            disabled_node.label(),
            Some("Previous 40 checks, unavailable on the first page")
        );
        assert!(!disabled_node.supports_action(accesskit::Action::Click));
        assert!(!disabled_node.supports_action(accesskit::Action::Focus));

        let activations = Rc::new(Cell::new(0));
        let (harness, cx) = cx.add_window_view({
            let activations = activations.clone();
            move |_, _| Harness {
                disabled: false,
                activations,
            }
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(point(px(10.), px(10.)), Modifiers::default());
        for key in ["enter", "space"] {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
        }
        assert_eq!(activations.get(), 3);

        harness.update(cx, |harness, cx| {
            harness.disabled = true;
            cx.notify();
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(point(px(10.), px(10.)), Modifiers::default());
        cx.simulate_keystrokes("enter space");
        assert_eq!(activations.get(), 3);
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn checks_native_navigation_reveals_offscreen_rows_and_preserves_exact_identity(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.repositories.push(RepoRuntime {
                    repository: repository.clone(),
                    pull_requests: Arc::new(vec![pull.clone()]),
                    state: LoadState::Ready,
                    generation: 0,
                    refresh: Default::default(),
                });
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                this.tabs[0].details = Some(checks_navigation_fixture(&repository, 81));
                this.tabs[0].details_state = LoadState::Ready;
                this.inspector_scroll.set_offset(point(px(0.), px(-900.)));
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });

        cx.dispatch_action(OpenChecks);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert!(matches!(
                this.tabs[0].inspector_section,
                InspectorSection::Checks
            ));
            assert_eq!(
                this.tabs[0].checks_selection.selected_id.as_deref(),
                Some("CHECK-0")
            );
        });

        for _ in 0..39 {
            cx.dispatch_action(NextCheck);
        }
        cx.update(|window, cx| window.draw(cx).clear(cx));
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert_eq!(
                this.tabs[0].checks_selection.selected_id.as_deref(),
                Some("CHECK-39")
            );
            assert_eq!(this.tabs[0].checks_selection.page, 0);
            assert!(this.inspector_scroll.top_item() <= 41);
            assert!(this.inspector_scroll.bottom_item() >= 41);
        });

        cx.dispatch_action(NextCheck);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert_eq!(
                this.tabs[0].checks_selection.selected_id.as_deref(),
                Some("CHECK-40")
            );
            assert_eq!(this.tabs[0].checks_selection.page, 1);
            assert!(this.inspector_scroll.top_item() <= 2);
            assert!(this.inspector_scroll.bottom_item() >= 2);
        });

        cx.dispatch_action(ToggleCheckIdentity);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert_eq!(
                this.tabs[0].checks_selection.expanded_id.as_deref(),
                Some("CHECK-40")
            );
            assert!(this.inspector_scroll.top_item() <= 2);
            assert!(this.inspector_scroll.bottom_item() >= 2);
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                let tab = &mut this.tabs[0];
                let details = tab.details.as_mut().unwrap();
                details.checks.rotate_left(17);
                tab.checks_selection.reconcile(&details.checks);
                this.scroll_selected_check_into_view(0);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert_eq!(
                this.tabs[0].checks_selection.selected_id.as_deref(),
                Some("CHECK-40")
            );
            assert_eq!(
                this.tabs[0].checks_selection.expanded_id.as_deref(),
                Some("CHECK-40")
            );
        });

        cx.dispatch_action(NextCheckPage);
        cx.dispatch_action(NextCheckPage);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        root.read_with(cx, |root, _| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            assert_eq!(this.tabs[0].checks_selection.page, 2);
            assert!(this.inspector_scroll.top_item() <= 2);
            assert!(this.inspector_scroll.bottom_item() >= 2);
        });

        cx.dispatch_action(ToggleCheckIdentity);
        cx.update(|window, cx| window.draw(cx).clear(cx));

        root.update(cx, |root, cx| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            let selected = this.tabs[0].checks_selection.selected_id.clone().unwrap();
            let tab = &mut this.tabs[0];
            let details = tab.details.as_mut().unwrap();
            details
                .checks
                .retain(|check| check.coordinates.remote_id != selected);
            let expected = details
                .checks
                .first()
                .map(|check| check.coordinates.remote_id.clone());
            tab.checks_selection.reconcile(&details.checks);
            assert!(tab.checks_selection.expanded_id.is_none());
            assert_eq!(
                tab.checks_selection.selected_id.as_deref(),
                expected.as_deref()
            );
            cx.notify();
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_root_apply_preserves_selected_refresh_and_fences_stale_ok_err(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        root.update(cx, |root, cx| {
            let Root::Review(this) = root else {
                unreachable!()
            };
            this.install_tab_with_restore(
                repository.clone(),
                pull,
                None,
                InstallTabOptions {
                    activate: true,
                    window: None,
                    start_background_work: false,
                },
                cx,
            );
            let details = actions_details_fixture(&repository);
            this.tabs[0].checks_selection.reconcile(&details.checks);
            this.tabs[0].details = Some(details);
            this.tabs[0].details_state = LoadState::Ready;
            let (_, locator, _, selected_check_id) = this.selected_actions_locator(0).unwrap();

            let initial = this.tabs[0].ci_read.begin_jobs(locator.clone());
            assert!(
                this.tabs[0]
                    .ci_read
                    .finish_jobs(&initial, Ok(actions_snapshot(&locator, 10, &[11, 12])),)
            );
            this.tabs[0].ci_read.select_job(Some(12));

            let refresh = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let refresh_token = CiCompletionToken {
                workspace_instance: this.workspace_instance,
                tab_instance: this.tabs[0].instance_generation,
                repository_key: repository.cache_key(),
                pull_request: 7,
                details_generation: this.tabs[0].details_generation,
                selected_check_id: selected_check_id.clone(),
                locator: locator.clone(),
                selected_job_id: this.tabs[0].ci_read.selected_job_id,
                jobs_observation_id: None,
                operation: refresh,
            };
            assert_eq!(refresh_token.selected_job_id, Some(12));
            assert!(this.apply_actions_jobs_completion(
                &refresh_token,
                Ok(actions_snapshot(&locator, 11, &[11, 12])),
            ));
            assert_eq!(this.tabs[0].ci_read.selected_job_id, Some(12));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Fresh(snapshot) if snapshot.observation_id == 11
            ));

            let exact_jobs = this.tabs[0].ci_read.jobs.visible().unwrap().clone();
            let (log_operation, _, selected_job_id) = this.tabs[0].ci_read.begin_log().unwrap();
            let log_token = CiCompletionToken {
                jobs_observation_id: Some(exact_jobs.observation_id),
                operation: log_operation,
                ..refresh_token.clone()
            };
            assert_eq!(selected_job_id, 12);
            this.tabs[0].ci_read.select_job(Some(11));
            assert!(
                !this.apply_actions_log_completion(&log_token, Ok(actions_log(&exact_jobs, 12)),)
            );
            assert!(!matches!(&this.tabs[0].ci_read.log, MemoryRead::Fresh(_)));
            this.tabs[0].ci_read.select_job(Some(12));

            let stale_operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let stale_token = CiCompletionToken {
                operation: stale_operation,
                ..refresh_token.clone()
            };
            let mut locator_b = locator.clone();
            locator_b.workflow_run.run_attempt = 3;
            let current = this.tabs[0].ci_read.begin_jobs(locator_b.clone());
            assert!(!this.apply_actions_jobs_completion(
                &stale_token,
                Ok(actions_snapshot(&locator, 12, &[11, 12])),
            ));
            assert!(!this.apply_actions_jobs_completion(
                &stale_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Unavailable,
                )),
            ));
            assert!(this.tabs[0].ci_read.owns(&current));
            assert_eq!(
                this.tabs[0].ci_read.frozen_locator.as_ref(),
                Some(&locator_b)
            );
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Loading { operation_id, .. }
                    if *operation_id == current.operation_id
            ));

            let stale_same_lifetime = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let stale_same_lifetime_token = CiCompletionToken {
                operation: stale_same_lifetime,
                selected_job_id: this.tabs[0].ci_read.selected_job_id,
                ..refresh_token.clone()
            };
            this.tabs[0].details_generation = this.tabs[0].details_generation.saturating_add(1);
            assert!(!this.apply_actions_jobs_completion(
                &stale_same_lifetime_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Cancelled,
                )),
            ));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Unavailable { .. }
            ));

            let replacement_operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let replacement_token = CiCompletionToken {
                workspace_instance: this.workspace_instance,
                details_generation: this.tabs[0].details_generation,
                operation: replacement_operation.clone(),
                ..refresh_token
            };
            this.workspace_instance = this.workspace_instance.saturating_add(1);
            assert!(!this.apply_actions_jobs_completion(
                &replacement_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Unavailable,
                )),
            ));
            assert!(this.tabs[0].ci_read.owns(&replacement_operation));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Loading { operation_id, .. }
                    if *operation_id == replacement_operation.operation_id
            ));
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_focus_tracks_preserved_pane_on_refusal_and_reopen(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        let busy_token = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let details = actions_details_fixture(&repository);
                this.tabs[0].checks_selection.reconcile(&details.checks);
                this.tabs[0].details = Some(details);
                this.tabs[0].details_state = LoadState::Ready;
                this.open_checks(window, cx);
                this.general_reads
                    .begin(&repository.account)
                    .unwrap()
                    .into_parts()
                    .0
            })
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));

        cx.dispatch_action(OpenSelectedCheckJobs);
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Checks);
                assert!(this.checks_focus.is_focused(window));
                assert!(!this.jobs_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                let disposition = this.general_reads.complete(
                    &busy_token,
                    &GeneralReadDirective::default(),
                    None,
                    false,
                );
                assert!(disposition.matching_operation_released);

                let (_, locator, _, _) = this.selected_actions_locator(0).unwrap();
                let operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
                assert!(
                    this.tabs[0]
                        .ci_read
                        .finish_jobs(&operation, Ok(actions_snapshot(&locator, 20, &[11, 12])),)
                );
                this.tabs[0].inspector_section = InspectorSection::Overview;
                this.focus.focus(window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });

        cx.dispatch_action(OpenChecks);
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert!(matches!(
                    this.tabs[0].inspector_section,
                    InspectorSection::Checks
                ));
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Jobs);
                assert!(this.jobs_focus.is_focused(window));
                assert!(!this.checks_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                let snapshot = this.tabs[0].ci_read.jobs.visible().unwrap().clone();
                let (operation, _, selected_job_id) = this.tabs[0].ci_read.begin_log().unwrap();
                assert!(
                    this.tabs[0]
                        .ci_read
                        .finish_log(&operation, Ok(actions_log(&snapshot, selected_job_id)),)
                );
                this.tabs[0].inspector_section = InspectorSection::Overview;
                this.focus.focus(window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        let checks_section = cx.debug_bounds("pr-tab-checks").unwrap();
        cx.simulate_click(checks_section.center(), Modifiers::default());
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert!(matches!(
                    this.tabs[0].inspector_section,
                    InspectorSection::Checks
                ));
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Log);
                assert!(this.log_focus.is_focused(window));
                assert!(!this.checks_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                let now = Instant::now();
                let (token, _) = this
                    .general_reads
                    .begin_at(&repository.account, now)
                    .unwrap()
                    .into_parts();
                let disposition = this.general_reads.complete_at(
                    &token,
                    &GeneralReadDirective {
                        x_poll_interval: None,
                        rate_limit: Some(GeneralReadDelay::Suspend),
                    },
                    None,
                    false,
                    now,
                    UNIX_EPOCH,
                );
                assert!(disposition.matching_operation_released);
                this.tabs[0].ci_read.pane = CiPane::Jobs;
                this.focus_current_ci_pane(0, window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        let load_log = cx.debug_bounds("actions-load-selected-log").unwrap();
        cx.simulate_click(load_log.center(), Modifiers::default());
        cx.update(|window, cx| {
            root.read_with(cx, |root, app| {
                let Root::Review(this) = root else {
                    unreachable!()
                };
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Jobs);
                assert!(this.jobs_focus.contains_focused(window, app));
                assert!(!this.log_focus.contains_focused(window, app));
                assert_eq!(this.status, super::read_sync::RATE_SUSPENDED_NOTICE);
            });
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
