    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn reaction_button_uses_pointer_enter_space_and_blocks_disabled_activation(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{
            Context, KeyDownEvent, KeyUpEvent, Keystroke, Modifiers, Render, div, point,
            prelude::*, px,
        };
        use gpui_base::Button;
        use std::{cell::Cell, rc::Rc};

        struct Harness {
            disabled: bool,
            activations: Rc<Cell<usize>>,
        }

        impl Render for Harness {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let activations = self.activations.clone();
                div().size(px(100.)).child(
                    Button::new("reaction-button-witness")
                        .size_full()
                        .disabled(self.disabled)
                        .accessibility_label("Add HEART reaction on IssueComment COMMENT")
                        .on_click(move |_, _, _| {
                            activations.set(activations.get() + 1);
                        }),
                )
            }
        }

        cx.update(gpui_base::init);
        let activations = Rc::new(Cell::new(0));
        let (harness, cx) = cx.add_window_view({
            let activations = activations.clone();
            move |_, _| Harness {
                disabled: false,
                activations,
            }
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(point(px(10.), px(10.)), Modifiers::default());
        assert_eq!(activations.get(), 1);
        for key in ["enter", "space"] {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
        }
        assert_eq!(activations.get(), 3);

        harness.update(cx, |harness, cx| {
            harness.disabled = true;
            cx.notify();
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(point(px(10.), px(10.)), Modifiers::default());
        cx.simulate_keystrokes("enter space");
        assert_eq!(activations.get(), 3);
    }

    /// The shared action helpers became native Buttons. This pins the three
    /// things that conversion could have broken: a control still activates
    /// exactly once from the pointer and once per Enter/Space, a disabled
    /// control activates from neither and does not leak its press to the row
    /// beneath it, and the control is still exactly one 28px data row high.
    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn converted_action_controls_fire_once_keep_row_height_and_block_disabled_activation(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{
            Context, KeyDownEvent, KeyUpEvent, Keystroke, Modifiers, Render, div, point,
            prelude::*, px,
        };
        use std::{cell::Cell, rc::Rc};

        struct Harness {
            disabled: bool,
            action: Rc<Cell<usize>>,
            row: Rc<Cell<usize>>,
        }

        impl Render for Harness {
            fn render(&mut self, _: &mut gpui::Window, _: &mut Context<Self>) -> impl IntoElement {
                let colors = super::palette(false);
                let action = self.action.clone();
                let row = self.row.clone();
                // The action sits inside a clickable row, which is how these
                // controls appear on the PR page.
                div()
                    .id("converted-action-row")
                    .tab_group()
                    .size(px(200.))
                    .on_click(move |_, _, _| row.set(row.get() + 1))
                    .child(
                        super::action_link_with_id(
                            "converted-action".into(),
                            "Review change…",
                            colors,
                        )
                        .debug_selector(|| "converted-action".into())
                        .disabled(self.disabled)
                        .on_click(move |_, _, _| action.set(action.get() + 1)),
                    )
            }
        }

        cx.update(gpui_base::init);
        let action = Rc::new(Cell::new(0));
        let row = Rc::new(Cell::new(0));
        let (harness, cx) = cx.add_window_view({
            let action = action.clone();
            let row = row.clone();
            move |_, _| Harness {
                disabled: false,
                action,
                row,
            }
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));

        let bounds = cx.debug_bounds("converted-action").unwrap();
        assert_eq!(
            bounds.size.height,
            px(cibergit::ui::CONTROL_HEIGHT),
            "a converted action must stay one 28px data row high"
        );

        // Tab first, with no pointer anywhere near the control. Reaching it by
        // pointer would prove nothing about tab-stop membership, and the ring is
        // keyboard-modality-only, so keyboard has to be the way in.
        let press = |cx: &mut gpui::VisualTestContext, key: &str| {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
        };
        press(cx, "tab");
        cx.update(|window, cx| {
            window.focus_next(cx);
            assert!(
                window.last_input_was_keyboard(),
                "a keystroke must put the window in keyboard modality, which is \
                 the only state in which focus-visible styling resolves"
            );
            assert!(
                window.focused(cx).is_some(),
                "the converted control must be a reachable tab stop"
            );
        });
        press(cx, "enter");
        press(cx, "space");
        assert_eq!(
            action.get(),
            2,
            "a control reached by Tab activates on Enter and on Space"
        );

        // Assert the ring on actual painted output, bounded to THIS control's
        // bounds and to the exact accent border it is supposed to gain.
        // Asserting only that focus exists cannot fail in a useful way, and
        // counting any accent quad anywhere would pass on an unrelated border.
        let accent: gpui::Hsla = super::palette(false).accent.into();
        let ring_on_control = |cx: &mut gpui::VisualTestContext| {
            cx.update(|window, _| {
                let scale = window.scale_factor();
                window
                    .painted_quads()
                    .into_iter()
                    .filter(|quad| {
                        quad.border_color == accent
                            && quad.border_widths.top > gpui::ScaledPixels(0.)
                            && quad.bounds == bounds.scale(scale)
                    })
                    .count()
            })
        };
        // GPUI emits one bordered quad per edge, so the count is its painting
        // detail, not a number worth pinning. What matters is that an accent
        // border is painted at THIS control's bounds and nowhere else.
        assert!(
            ring_on_control(cx) > 0,
            "the keyboard-focused control must paint an accent ring at its own \
             bounds"
        );

        // The ring is keyboard-only: the same press that activates by pointer
        // must also take the ring away.
        let inside = bounds.origin + point(px(4.), px(4.));
        cx.simulate_click(inside, Modifiers::default());
        assert_eq!(action.get(), 3, "one pointer press is one activation");
        cx.update(|window, cx| {
            assert!(
                !window.last_input_was_keyboard(),
                "a pointer press must leave keyboard modality"
            );
            window.draw(cx).clear(cx);
        });
        assert_eq!(
            ring_on_control(cx),
            0,
            "the same control must drop its ring under mouse modality"
        );

        let row_activations_while_enabled = row.get();
        harness.update(cx, |harness, cx| {
            harness.disabled = true;
            cx.notify();
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.simulate_click(inside, Modifiers::default());
        cx.simulate_keystrokes("enter space");
        assert_eq!(action.get(), 3, "a disabled action is inert");
        assert_eq!(
            row.get(),
            row_activations_while_enabled,
            "a press on a disabled action must not fall through to the row"
        );
    }

    #[test]
    fn reaction_completion_fence_captures_every_identity_and_identical_action_aba() {
        let coordinates = |id: &str| ProviderCoordinates {
            provider: "github".into(),
            host: "github.com".into(),
            owner: "octo".into(),
            repository: "repo".into(),
            pull_request: 7,
            remote_id: id.into(),
        };
        let token = ReactionCompletionToken {
            workspace_instance: 10,
            tab_instance: 20,
            repository_key: "account/repository".into(),
            pull_request: 7,
            subject: coordinates("COMMENT"),
            parent_review: Some(coordinates("REVIEW")),
            content: ReactionContent::Heart,
            intent: ReactionIntent::Remove,
            operation_id: "reaction-operation".into(),
            attempt_id: "reaction-attempt".into(),
            generation: 30,
        };
        assert!(token.matches_fence(10, 20, "account/repository", 7, Some(&token)));
        assert!(!token.matches_fence(11, 20, "account/repository", 7, Some(&token)));
        assert!(!token.matches_fence(10, 21, "account/repository", 7, Some(&token)));
        assert!(!token.matches_fence(10, 20, "other-account/repository", 7, Some(&token)));
        assert!(!token.matches_fence(10, 20, "account/repository", 8, Some(&token)));
        assert!(!token.matches_fence(10, 20, "account/repository", 7, None));

        for changed in [
            {
                let mut value = token.clone();
                value.subject = coordinates("OTHER_COMMENT");
                value
            },
            {
                let mut value = token.clone();
                value.parent_review = Some(coordinates("OTHER_REVIEW"));
                value
            },
            {
                let mut value = token.clone();
                value.content = ReactionContent::Eyes;
                value
            },
            {
                let mut value = token.clone();
                value.intent = ReactionIntent::Add;
                value
            },
            {
                let mut value = token.clone();
                value.operation_id = "other-operation".into();
                value
            },
            {
                let mut value = token.clone();
                value.attempt_id = "other-attempt".into();
                value
            },
            {
                let mut value = token.clone();
                value.generation = 31;
                value
            },
        ] {
            assert!(
                !token.matches_fence(10, 20, "account/repository", 7, Some(&changed)),
                "a newer full-fence action must not be cleared by a stale callback"
            );
        }
    }

    #[test]
    fn explicit_refresh_coalesces_and_discards_the_pre_effect_observation() {
        let mut lane = super::RefreshGate::default();
        assert!(lane.request(false));
        // A mutation completed or the sidebar filter changed while its older
        // read was active. Repeated explicit requests retain one fresh read.
        for _ in 0..10 {
            assert!(!lane.request(true));
            assert!(!lane.request(false));
        }
        let mut displayed = "retained cache";
        let refresh_again = lane.complete();
        if !refresh_again {
            displayed = "pre-effect observation";
        }
        assert!(refresh_again);
        assert_eq!(displayed, "retained cache");
        assert!(lane.request(true));
        for _ in 0..20 {
            assert!(!lane.request(false));
        }
        assert!(!lane.complete(), "polls must not queue a third read");
        displayed = "post-effect observation";
        assert_eq!(displayed, "post-effect observation");
        // Errors finish the same lane, so a subsequent explicit retry can run.
        assert!(lane.request(true));
        assert!(!lane.complete());
        assert!(lane.request(true));
    }

    #[test]
    fn explicit_follow_up_retains_server_poll_floor_without_stranding_lane() {
        let now = Instant::now();
        let wall = UNIX_EPOCH + Duration::from_secs(40_000);
        let account = Account {
            host: "github.com".into(),
            login: "alice".into(),
        };
        let mut lane = super::RefreshGate::default();
        let mut reads = super::read_sync::GeneralReadController::default();
        assert_eq!(lane.begin_admission(false), Some(false));
        let (token, _) = reads.begin_at(&account, now).unwrap().into_parts();
        assert_eq!(lane.begin_admission(true), None);
        let follow_up = lane.complete();
        assert!(follow_up);
        let disposition = reads.complete_at(
            &token,
            &GeneralReadDirective {
                x_poll_interval: Some(GeneralReadDelay::Seconds(90)),
                rate_limit: None,
            },
            None,
            false,
            now,
            wall,
        );
        assert!(disposition.matching_operation_released);
        assert!(!disposition.payload_accepted);

        assert_eq!(lane.begin_admission(true), Some(true));
        let deferral = reads.begin_at(&account, now + Duration::from_secs(89));
        assert!(matches!(
            deferral,
            Err(super::read_sync::ReadDeferral::Server(
                super::read_sync::POLL_DEFERRED_NOTICE
            ))
        ));
        lane.defer_admission(true);
        assert!(lane.has_deferred());
        assert_eq!(lane.begin_admission(false), Some(true));
        assert!(
            reads
                .begin_at(&account, now + Duration::from_secs(90))
                .is_ok()
        );
    }

    #[test]
    fn periodic_cycle_fairly_dispatches_all_same_account_lanes() {
        let now = Instant::now();
        let wall = UNIX_EPOCH + Duration::from_secs(50_000);
        let account = Account {
            host: "github.com".into(),
            login: "alice".into(),
        };
        // Metadata, details, lifecycle, then a later sidebar repository.
        let mut lanes: [super::RefreshGate; 4] = std::array::from_fn(|_| Default::default());
        let mut reads = super::read_sync::GeneralReadController::default();
        let mut dispatched = [0usize; 4];

        assert_eq!(lanes[0].begin_admission(false), Some(false));
        let (metadata, _) = reads.begin_at(&account, now).unwrap().into_parts();
        dispatched[0] += 1;
        for lane in &mut lanes[1..] {
            let explicit = lane.begin_admission(false).unwrap();
            assert!(matches!(
                reads.begin_at(&account, now),
                Err(super::read_sync::ReadDeferral::Busy)
            ));
            lane.defer_admission(explicit);
            assert!(lane.has_deferred());
        }
        assert!(
            reads
                .complete_at(
                    &metadata,
                    &GeneralReadDirective::default(),
                    None,
                    false,
                    now,
                    wall,
                )
                .matching_operation_released
        );
        assert!(!lanes[0].complete());

        let mut cursor = 0usize;
        while dispatched.contains(&0) {
            let mut pending = (0..lanes.len())
                .filter(|index| lanes[*index].has_deferred())
                .collect::<Vec<_>>();
            super::rotate_general_read_followups(&mut pending, &mut cursor);
            let mut started = None;
            for index in pending {
                let explicit = lanes[index].begin_admission(false).unwrap();
                match reads.begin_at(&account, now) {
                    Ok(admission) => {
                        dispatched[index] += 1;
                        started = Some((index, admission.into_parts().0));
                    }
                    Err(super::read_sync::ReadDeferral::Busy) => {
                        lanes[index].defer_admission(explicit)
                    }
                    Err(other) => panic!("unexpected server deferral: {other:?}"),
                }
            }
            let (started_index, token) = started.expect("one pending lane must dispatch");

            // Another periodic tick while this lane is active re-coalesces the
            // other automatic intents. The rotating resume order must still
            // reach lifecycle and the later repository.
            for (index, lane) in lanes.iter_mut().enumerate() {
                if let Some(explicit) = lane.begin_admission(false) {
                    match reads.begin_at(&account, now) {
                        Ok(_) => panic!("periodic work overlapped lane {started_index}"),
                        Err(super::read_sync::ReadDeferral::Busy) => lane.defer_admission(explicit),
                        Err(other) => panic!("unexpected server deferral: {other:?}"),
                    }
                } else {
                    assert_eq!(index, started_index);
                }
            }
            assert!(
                reads
                    .complete_at(
                        &token,
                        &GeneralReadDirective::default(),
                        None,
                        false,
                        now,
                        wall,
                    )
                    .matching_operation_released
            );
            assert!(!lanes[started_index].complete());
        }
        assert_eq!(dispatched, [1, 1, 1, 1]);
    }

    #[test]
    fn stale_workspace_ok_and_error_callbacks_mutate_no_lane_or_ui_state() {
        for result in ["ok", "error"] {
            let mut lane = super::RefreshGate::default();
            assert_eq!(lane.begin_admission(false), Some(false));
            let mut status = "replacement status";
            let mut state = "replacement state";
            let mut schedule = "replacement schedule";
            if super::general_read_callback_is_current(10, 11) {
                lane.complete();
                status = result;
                state = result;
                schedule = result;
            }
            assert!(
                lane.active,
                "stale callback must not release replacement lane"
            );
            assert_eq!(status, "replacement status");
            assert_eq!(state, "replacement state");
            assert_eq!(schedule, "replacement schedule");
        }
    }

